UPDATE cards c
INNER JOIN card_content_versions cv ON cv.card_id = c.card_id
SET c.gorilla_card_id = SUBSTRING_INDEX(cv.source_url, '/', -1)
WHERE c.gorilla_card_id IS NULL
  AND cv.source_url LIKE 'https://www.card-gorilla.com/card/detail/%';
