    ('2f1b4ee1-dcf0-56ce-ac44-5fe534bc85a5', (SELECT cv.content_version_id FROM card_content_versions cv INNER JOIN cards c ON c.card_id = cv.card_id WHERE c.gorilla_card_id = '575' AND cv.content_sha256 = 'e894fb1aaddd7faa365b07914b912f83db8054a97c65627819fb2277c8941d0c'), 6, 7, 'benefit', '기타', '[국내 서비스] 우체국 5%', '[국내 서비스]
