INSERT INTO benefit_rule_targets
(target_id, rule_id, condition_group, match_mode, target_type,
 merchant_category_id, merchant_id, target_code, target_name, created_at, updated_at)
SELECT seed.target_id, seed.rule_id, seed.condition_group, seed.match_mode, seed.target_type,
       category.merchant_category_id, NULL, seed.target_code, seed.target_name,
       seed.created_at, seed.updated_at
FROM seed_legacy_targets seed
LEFT JOIN merchant_categories category ON category.category_code=seed.target_code
WHERE seed.target_type='all_merchants' OR category.merchant_category_id IS NOT NULL
ON DUPLICATE KEY UPDATE target_name=VALUES(target_name), updated_at=VALUES(updated_at);

