-- A. 현대카드Z work Edition2
-- ---------------------------------------------------------------------------------
INSERT INTO moca.cards (card_id, issuer_id, gorilla_card_id, card_type, first_seen_at, last_seen_at)
SELECT UUID(), issuer_id, '2680', 'credit', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)
FROM moca.issuers
WHERE issuer_name = '현대카드'
  AND NOT EXISTS (SELECT 1 FROM moca.cards WHERE gorilla_card_id = '2680')
LIMIT 1;

INSERT INTO moca.card_content_versions
(content_version_id, card_id, content_sha256, name, discontinued, main_benefits, image_url, first_seen_at, last_seen_at)
SELECT UUID(), c.card_id, SHA2('HD_Z_WORK_ED2_V1', 256),
       '현대카드Z work Edition2', 0,
       '편의점 10% 청구 할인(GS25·CU·세븐일레븐·이마트24, 1일 1회)\n커피전문점 10% 청구 할인(스타벅스·투썸플레이스·커피빈·폴바셋, 1일 1회)\n도서 10% 청구 할인(교보문고·YES24, 1일 1회)\n각 영역 전월 이용금액 50만원 이상 월 6천원, 100만원 이상 월 1만원\n백화점·할인점·쇼핑몰 입점 및 공동가맹점 제외\n도서 온라인은 공식 홈페이지·앱 결제만 적용',
       'https://d1c5n4ri2guedi.cloudfront.net/card/2680/card_img/39646/2680card.png',
       CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)
FROM moca.cards c
WHERE c.gorilla_card_id = '2680'
  AND NOT EXISTS (
      SELECT 1 FROM moca.card_content_versions cv
      WHERE cv.card_id = c.card_id AND cv.content_sha256 = SHA2('HD_Z_WORK_ED2_V1', 256)
  );

SET @HDZ_CV := (
    SELECT content_version_id
    FROM moca.card_content_versions
    WHERE card_id = (SELECT card_id FROM moca.cards WHERE gorilla_card_id = '2680' LIMIT 1)
      AND content_sha256 = SHA2('HD_Z_WORK_ED2_V1', 256)
    LIMIT 1
);

