INSERT INTO moca.benefit_rule_targets
(target_id, rule_id, condition_group, match_mode, target_type,
 merchant_category_id, merchant_id, target_code, target_name)
SELECT UUID(), r.rule_id, x.condition_group, x.match_mode, x.target_type,
       category.merchant_category_id, merchant.merchant_id, x.target_code, x.target_name
FROM (
    SELECT '온라인 쇼핑 10% 청구 할인' offer_name, 1 condition_group, 'include' match_mode, 'merchant' target_type, '네이버쇼핑' target_code, '네이버쇼핑' target_name UNION ALL
    SELECT '온라인 쇼핑 10% 청구 할인',2,'include','merchant','쿠팡','쿠팡' UNION ALL
    SELECT '온라인 쇼핑 10% 청구 할인',3,'include','merchant','G마켓','G마켓' UNION ALL
    SELECT '온라인 쇼핑 10% 청구 할인',4,'include','merchant','옥션','옥션' UNION ALL
    SELECT '온라인 쇼핑 10% 청구 할인',5,'include','merchant','11번가','11번가' UNION ALL
    SELECT '온라인 쇼핑 10% 청구 할인',6,'include','merchant','SSG.COM','SSG.COM' UNION ALL
    SELECT '온라인 쇼핑 10% 청구 할인',7,'include','merchant','컬리','컬리' UNION ALL
    SELECT '편의점 10% 청구 할인',1,'include','merchant_category','CONVENIENCE_STORE','편의점' UNION ALL
    SELECT '커피전문점 10% 청구 할인',1,'include','merchant_category','CAFE','커피전문점' UNION ALL
    SELECT '대중교통 10% 청구 할인',1,'include','merchant_category','TRANSPORTATION','교통' UNION ALL
    SELECT '도서 10% 청구 할인',1,'include','merchant','교보문고','교보문고' UNION ALL
    SELECT '도서 10% 청구 할인',2,'include','merchant','YES24','YES24'
) x
JOIN moca.benefit_offers o ON o.offer_name=x.offer_name
JOIN moca.card_benefits b ON b.benefit_id=o.benefit_id AND b.content_version_id=@HDZ_CV
JOIN moca.benefit_rules r ON r.offer_id=o.offer_id
LEFT JOIN moca.merchant_categories category
  ON x.target_type='merchant_category' AND category.category_code=x.target_code
LEFT JOIN moca.merchants merchant
  ON x.target_type='merchant'
 AND (merchant.normalized_name=x.target_code OR merchant.name=x.target_code)
WHERE NOT EXISTS (
    SELECT 1 FROM moca.benefit_rule_targets t
    WHERE t.rule_id=r.rule_id AND t.condition_group=x.condition_group
      AND t.match_mode=x.match_mode AND t.target_type=x.target_type AND t.target_code=x.target_code
)
  AND (x.target_type='all_merchants'
       OR (x.target_type='merchant_category' AND category.merchant_category_id IS NOT NULL)
       OR (x.target_type='merchant' AND merchant.merchant_id IS NOT NULL));

