       'https://d1c5n4ri2guedi.cloudfront.net/card/2899/card_img/44318/2899card.png',
       0,
       '주유, 쇼핑, 배달 최대 5% 적립\nOTT, 멤버십 최대 1만 5천원 적립\n포인트박스 10% 추가 입금',
       CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)
FROM moca.cards c
WHERE c.gorilla_card_id='2899'
  AND NOT EXISTS (
      SELECT 1 FROM moca.card_content_versions cv
      WHERE cv.card_id=c.card_id AND cv.content_sha256=SHA2('SH_SOL_PLAN_V1',256)
  );

SET @SOL_CV := (
    SELECT content_version_id
    FROM moca.card_content_versions
    WHERE card_id=(SELECT card_id FROM moca.cards WHERE gorilla_card_id='2899' LIMIT 1)
      AND content_sha256=SHA2('SH_SOL_PLAN_V1',256)
    LIMIT 1
);

