INSERT INTO moca.card_benefits
(benefit_id, content_version_id, position, record_type, title, summary)
SELECT UUID(), @SOL_CV, 1, 'benefit', '쓸수록 SOLSOL 서비스', '국내/외 기본 1~1.5% 및 특별영역 2.5~5% 적립'
WHERE NOT EXISTS (SELECT 1 FROM moca.card_benefits WHERE content_version_id=@SOL_CV AND position=1)
UNION ALL
SELECT UUID(), @SOL_CV, 2, 'benefit', '담을수록 SOLSOL 서비스', 'OTT/멤버십 최대 1만5천 SOL포인트 적립'
WHERE NOT EXISTS (SELECT 1 FROM moca.card_benefits WHERE content_version_id=@SOL_CV AND position=2)
UNION ALL
SELECT UUID(), @SOL_CV, 3, 'benefit', '모을수록 SOLSOL 서비스', '포인트박스 10% 추가 입금'
WHERE NOT EXISTS (SELECT 1 FROM moca.card_benefits WHERE content_version_id=@SOL_CV AND position=3);

SET @SOL_POINT_PROGRAM := (
    SELECT rp.reward_program_id
    FROM moca.reward_programs rp
    JOIN moca.issuers i ON i.issuer_id=rp.issuer_id
    WHERE rp.program_name='SOL포인트' AND i.issuer_name='신한카드'
    LIMIT 1
);

INSERT INTO moca.benefit_offers
(offer_id, benefit_id, reward_program_id, offer_name, position, reward_type, value_type,
 calculation_mode, calculation_basis, stacking_mode, valuation_scope, valuation_method)
SELECT UUID(), b.benefit_id, @SOL_POINT_PROGRAM, '국내/외 전가맹점 기본 적립', 1,
       'points','percentage','progressive_tier','transaction_amount','standalone','transaction','direct'
FROM moca.card_benefits b
WHERE b.content_version_id=@SOL_CV AND b.position=1
  AND NOT EXISTS (SELECT 1 FROM moca.benefit_offers o WHERE o.benefit_id=b.benefit_id AND o.position=1)
UNION ALL
SELECT UUID(), b.benefit_id, @SOL_POINT_PROGRAM, '특별 적립 (주유/쇼핑/배달)', 2,
       'points','percentage','progressive_tier','transaction_amount','replace','transaction','direct'
FROM moca.card_benefits b
WHERE b.content_version_id=@SOL_CV AND b.position=1
  AND NOT EXISTS (SELECT 1 FROM moca.benefit_offers o WHERE o.benefit_id=b.benefit_id AND o.position=2)
UNION ALL
SELECT UUID(), b.benefit_id, @SOL_POINT_PROGRAM, 'OTT/멤버십 특별 적립', 1,
       'points','fixed_amount','single_tier','usage_count','standalone','transaction','direct'
FROM moca.card_benefits b
WHERE b.content_version_id=@SOL_CV AND b.position=2
  AND NOT EXISTS (SELECT 1 FROM moca.benefit_offers o WHERE o.benefit_id=b.benefit_id AND o.position=1)
UNION ALL
SELECT UUID(), b.benefit_id, @SOL_POINT_PROGRAM, '포인트박스 10% 추가 입금', 1,
       'points','percentage','flat','other','additive','annual','not_valued'
FROM moca.card_benefits b
WHERE b.content_version_id=@SOL_CV AND b.position=3
  AND NOT EXISTS (SELECT 1 FROM moca.benefit_offers o WHERE o.benefit_id=b.benefit_id AND o.position=1);

