INSERT INTO moca.benefit_rule_targets
(target_id, rule_id, condition_group, match_mode, target_type,
 merchant_category_id, merchant_id, target_code, target_name)
SELECT UUID(), r.rule_id, x.condition_group, x.match_mode, x.target_type,
       category.merchant_category_id, merchant.merchant_id, x.target_code, x.target_name
FROM (
    SELECT '특별 적립 (주유/쇼핑/배달)' offer_name,1 condition_group,'include' match_mode,'merchant' target_type,'SK에너지' target_code,'SK에너지' target_name UNION ALL
    SELECT '특별 적립 (주유/쇼핑/배달)',1,'include','merchant','GS칼텍스','GS칼텍스' UNION ALL
    SELECT '특별 적립 (주유/쇼핑/배달)',2,'include','merchant','쿠팡','쿠팡' UNION ALL
    SELECT '특별 적립 (주유/쇼핑/배달)',2,'include','merchant','SSG.COM','SSG.COM' UNION ALL
    SELECT '특별 적립 (주유/쇼핑/배달)',2,'include','merchant','무신사','무신사' UNION ALL
    SELECT '특별 적립 (주유/쇼핑/배달)',2,'include','merchant','29CM','29CM' UNION ALL
    SELECT '특별 적립 (주유/쇼핑/배달)',3,'include','merchant','땡겨요','땡겨요' UNION ALL
    SELECT '특별 적립 (주유/쇼핑/배달)',3,'include','merchant','배달의민족','배달의민족' UNION ALL
    SELECT '특별 적립 (주유/쇼핑/배달)',3,'include','merchant','요기요','요기요' UNION ALL
    SELECT '특별 적립 (주유/쇼핑/배달)',3,'include','merchant','쿠팡이츠','쿠팡이츠' UNION ALL
    SELECT 'OTT/멤버십 특별 적립',1,'include','merchant','넷플릭스','넷플릭스' UNION ALL
    SELECT 'OTT/멤버십 특별 적립',1,'include','merchant','유튜브 프리미엄','유튜브 프리미엄' UNION ALL
    SELECT 'OTT/멤버십 특별 적립',1,'include','merchant','티빙','티빙' UNION ALL
    SELECT 'OTT/멤버십 특별 적립',1,'include','merchant','디즈니플러스','디즈니플러스' UNION ALL
    SELECT 'OTT/멤버십 특별 적립',1,'include','merchant','네이버플러스 멤버십','네이버플러스 멤버십' UNION ALL
    SELECT 'OTT/멤버십 특별 적립',1,'include','merchant','쿠팡 와우 멤버십','쿠팡 와우 멤버십'
) x
JOIN moca.benefit_offers o ON o.offer_name=x.offer_name
JOIN moca.card_benefits b ON b.benefit_id=o.benefit_id AND b.content_version_id=@SOL_CV
JOIN moca.benefit_rules r ON r.offer_id=o.offer_id
LEFT JOIN moca.merchant_categories category
  ON x.target_type='merchant_category' AND category.category_code=x.target_code
LEFT JOIN moca.merchants merchant
  ON x.target_type='merchant'
 AND (merchant.normalized_name=x.target_code OR merchant.name=x.target_code)
WHERE NOT EXISTS (
    SELECT 1 FROM moca.benefit_rule_targets t
    WHERE t.rule_id=r.rule_id AND t.condition_group=x.condition_group
      AND t.match_mode=x.match_mode AND t.target_type=x.target_type AND t.target_code=x.target_code
)
  AND (x.target_type='all_merchants'
       OR (x.target_type='merchant_category' AND category.merchant_category_id IS NOT NULL)
       OR (x.target_type='merchant' AND merchant.merchant_id IS NOT NULL));


-- =================================================================================
-- 카드 혜택 자체에서 필요한 내부 카테고리 보강
-- Kakao 18개를 이유로 내부 taxonomy를 만들지 않는다.
-- =================================================================================

-- 실제 카드 혜택/제외 조건에 존재하는 범주만 추가
INSERT INTO moca.merchant_categories
(merchant_category_id, parent_id, category_code, category_name, display_order,
 is_map_visible, created_at, updated_at)
SELECT UUID(), NULL, x.category_code, x.category_name, x.display_order,
       x.is_map_visible, CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)
FROM (
    SELECT 'PARKING' category_code, '주차장' category_name, 33 display_order, TRUE is_map_visible
    UNION ALL SELECT 'BANK', '은행', 34, FALSE
    UNION ALL SELECT 'ACCOMMODATION', '숙박', 35, TRUE
) x
WHERE NOT EXISTS (
    SELECT 1
    FROM moca.merchant_categories mc
    WHERE mc.category_code = x.category_code
);

