SET parent_id = (SELECT x.merchant_category_id
                 FROM (SELECT merchant_category_id
                       FROM moca.merchant_categories
                       WHERE category_code='PUBLIC_TRANSIT' LIMIT 1) x),
    updated_at = CURRENT_TIMESTAMP(6)
WHERE category_code IN ('BUS','SUBWAY');

