-- 카카오 카테고리도 가능한 경우 카드 혜택의 세부 leaf category로 연결한다.
-- PS3/SC4/AC5/SW8은 상위 카테고리보다 이 leaf가 계산에 더 적합하다.
UPDATE moca.kakao_category_maps km
JOIN moca.merchant_categories mc ON mc.category_code='PRESCHOOL'
SET km.merchant_category_id=mc.merchant_category_id
WHERE km.kakao_category_group_code='PS3';

UPDATE moca.kakao_category_maps km
JOIN moca.merchant_categories mc ON mc.category_code='SCHOOL'
SET km.merchant_category_id=mc.merchant_category_id
WHERE km.kakao_category_group_code='SC4';

UPDATE moca.kakao_category_maps km
JOIN moca.merchant_categories mc ON mc.category_code='ACADEMY'
SET km.merchant_category_id=mc.merchant_category_id
WHERE km.kakao_category_group_code='AC5';

UPDATE moca.kakao_category_maps km
JOIN moca.merchant_categories mc ON mc.category_code='SUBWAY'
SET km.merchant_category_id=mc.merchant_category_id
WHERE km.kakao_category_group_code='SW8';

-- 원본 카테고리가 명확한 계산 가능 Rule에 category target을 보강한다.
-- 기존 merchant/category target은 유지하며 중복만 방지한다.
INSERT INTO moca.benefit_rule_targets
(target_id, rule_id, condition_group, match_mode, target_type,
 merchant_category_id, merchant_id, target_code, target_name, created_at, updated_at)
SELECT UUID(), r.rule_id, 1, 'include', 'merchant_category',
       mc.merchant_category_id, NULL, mc.category_code, mc.category_name,
       CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)
FROM moca.card_benefits b
JOIN moca.benefit_offers o ON o.benefit_id=b.benefit_id
JOIN moca.benefit_rules r ON r.offer_id=o.offer_id
JOIN moca.card_gorilla_category_maps gm
  ON gm.source_category_id=b.source_category_id
 AND gm.enabled=TRUE
JOIN moca.merchant_categories mc
  ON mc.merchant_category_id=gm.merchant_category_id
WHERE b.source_category_id IN (9,13,14,18,19,20,21,23,24,35,48,50,51,52,53,55,70,71,75,76,77,90,96,97,99,107,110,112,113,114,115,117,118,120,122,125,127,129,133,135,136,139,141,145,159,160,165,166,167,169,185)
  AND NOT EXISTS (
      SELECT 1
      FROM moca.benefit_rule_targets t
      WHERE t.rule_id=r.rule_id
        AND t.match_mode='include'
        AND t.target_type='merchant_category'
        AND t.target_code=mc.category_code
  );



-- 의료 원문 scope는 변환 과정에서만 임시 보관하고 최종적으로 benefit_rule_targets에 통합한다.
CREATE TEMPORARY TABLE moca.benefit_medical_scopes (
    benefit_medical_scope_id CHAR(36) NOT NULL,
    benefit_id CHAR(36) NOT NULL,
    merchant_category_id CHAR(36) NOT NULL,
    match_mode VARCHAR(16) NOT NULL,
    reason_text VARCHAR(500) NULL,
    created_at DATETIME(6) NOT NULL,
    updated_at DATETIME(6) NOT NULL,
    PRIMARY KEY (benefit_medical_scope_id),
    UNIQUE KEY uk_seed_medical_scope (benefit_id, merchant_category_id, match_mode)
) ENGINE=InnoDB;

-- 카드고릴라 원문을 근거로 확정된 include/exclude만 적재한다.

INSERT IGNORE INTO moca.benefit_medical_scopes
(benefit_medical_scope_id, benefit_id, merchant_category_id, match_mode,
 reason_text, created_at, updated_at)
SELECT UUID(), b.benefit_id, mc.merchant_category_id, 'include',
       '병원/약국 할인, 동물병원 제외, 치과/한의원 포함', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)
FROM moca.cards c
JOIN moca.card_content_versions cv ON cv.card_id=c.card_id
JOIN moca.card_benefits b ON b.content_version_id=cv.content_version_id AND b.position=3
JOIN moca.merchant_categories mc ON mc.category_code='HOSPITAL'
WHERE c.gorilla_card_id='13';

