-- =================================================================================
-- 최종 정규화: Kakao registry / 안전한 mapping / merchant FK / category hierarchy
-- =================================================================================

-- -----------------------------------------------------------------------------
-- 1) Kakao 공식 18개 코드는 외부 레지스트리에 전부 보존
--    내부 카드혜택 계산과 직접 연결하지 않는 코드는 supported=FALSE
-- -----------------------------------------------------------------------------
INSERT INTO moca.kakao_category_group_registry
(kakao_category_group_code, kakao_category_group_name,
 benefit_mapping_supported, note, created_at, updated_at)
VALUES
('MT1','대형마트',TRUE,'카드 혜택 LARGE_MART와 직접 연결 가능',CURRENT_TIMESTAMP(6),CURRENT_TIMESTAMP(6)),
('CS2','편의점',TRUE,'카드 혜택 CONVENIENCE_STORE와 직접 연결 가능',CURRENT_TIMESTAMP(6),CURRENT_TIMESTAMP(6)),
('PS3','어린이집, 유치원',TRUE,'교육/육아 혜택 세부 카테고리와 연결',CURRENT_TIMESTAMP(6),CURRENT_TIMESTAMP(6)),
('SC4','학교',TRUE,'학교 혜택 세부 카테고리와 연결',CURRENT_TIMESTAMP(6),CURRENT_TIMESTAMP(6)),
('AC5','학원',TRUE,'학원 혜택 세부 카테고리와 연결',CURRENT_TIMESTAMP(6),CURRENT_TIMESTAMP(6)),
('PK6','주차장',TRUE,'주차장 혜택/제외 조건과 연결 가능',CURRENT_TIMESTAMP(6),CURRENT_TIMESTAMP(6)),
('OL7','주유소, 충전소',TRUE,'주유소와 전기차 충전소를 pattern으로 분리',CURRENT_TIMESTAMP(6),CURRENT_TIMESTAMP(6)),
('SW8','지하철역',TRUE,'SUBWAY와 직접 연결',CURRENT_TIMESTAMP(6),CURRENT_TIMESTAMP(6)),
('BK9','은행',FALSE,'은행 위치 자체는 현재 오프라인 결제 혜택 계산 대상이 아님',CURRENT_TIMESTAMP(6),CURRENT_TIMESTAMP(6)),
('CT1','문화시설',TRUE,'세부 공연/전시 pattern만 계산 허용, broad group은 표시용',CURRENT_TIMESTAMP(6),CURRENT_TIMESTAMP(6)),
('AG2','중개업소',FALSE,'카드고릴라 혜택 taxonomy에 위치기반 중개업소 혜택 없음',CURRENT_TIMESTAMP(6),CURRENT_TIMESTAMP(6)),
('PO3','공공기관',FALSE,'공공기관은 주로 실적/할인 제외 조건이며 지도 추천 계산과 직접 연결하지 않음',CURRENT_TIMESTAMP(6),CURRENT_TIMESTAMP(6)),
('AT4','관광명소',FALSE,'TRAVEL 혜택과 관광명소를 동일시하지 않음',CURRENT_TIMESTAMP(6),CURRENT_TIMESTAMP(6)),
('AD5','숙박',TRUE,'ACCOMMODATION과 직접 연결',CURRENT_TIMESTAMP(6),CURRENT_TIMESTAMP(6)),
('FD6','음식점',TRUE,'RESTAURANT와 직접 연결',CURRENT_TIMESTAMP(6),CURRENT_TIMESTAMP(6)),
('CE7','카페',TRUE,'CAFE와 직접 연결',CURRENT_TIMESTAMP(6),CURRENT_TIMESTAMP(6)),
('HP8','병원',TRUE,'의료 상세 pattern으로 세분화한 경우만 계산 허용',CURRENT_TIMESTAMP(6),CURRENT_TIMESTAMP(6)),
('PM9','약국',TRUE,'PHARMACY와 직접 연결',CURRENT_TIMESTAMP(6),CURRENT_TIMESTAMP(6))
ON DUPLICATE KEY UPDATE
    kakao_category_group_name=VALUES(kakao_category_group_name),
    benefit_mapping_supported=VALUES(benefit_mapping_supported),
    note=VALUES(note),
    updated_at=VALUES(updated_at);

-- 과거 seed에서 Kakao 때문에 생성했던 내부 범주는 참조가 없을 때만 제거
DELETE mc
FROM moca.merchant_categories mc
LEFT JOIN moca.merchants m
  ON m.merchant_category_id=mc.merchant_category_id
LEFT JOIN moca.merchant_categories child
  ON child.parent_id=mc.merchant_category_id
LEFT JOIN moca.benefit_rule_targets t
  ON t.target_type='merchant_category'
 AND t.target_code=mc.category_code
WHERE mc.category_code IN ('REAL_ESTATE','PUBLIC_AGENCY')
  AND m.merchant_id IS NULL
  AND child.merchant_category_id IS NULL
  AND t.target_id IS NULL;

-- Kakao mapping은 한번 정리한 뒤, 혜택 계산에 안전한 것만 다시 적재
DELETE FROM moca.kakao_category_maps;

-- 명확한 group-code 매핑
INSERT INTO moca.kakao_category_maps
(kakao_category_map_id, merchant_category_id, kakao_category_group_code,
 kakao_category_name_pattern, match_method, confidence_score,
 benefit_match_policy, priority, enabled, created_at, updated_at)
SELECT UUID(), mc.merchant_category_id, x.kakao_code, COALESCE(x.pattern_name, ''),
       x.match_method, x.confidence_score, x.policy,
       x.priority, TRUE, CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)
FROM (
    SELECT 'LARGE_MART' category_code,'MT1' kakao_code,NULL pattern_name,'GROUP_CODE' match_method,0.980 confidence_score,'ALLOW' policy,1 priority
    UNION ALL SELECT 'CONVENIENCE_STORE','CS2',NULL,'GROUP_CODE',0.990,'ALLOW',1
    UNION ALL SELECT 'PRESCHOOL','PS3',NULL,'GROUP_CODE',0.950,'DISPLAY_ONLY',1
    UNION ALL SELECT 'SCHOOL','SC4',NULL,'GROUP_CODE',0.950,'DISPLAY_ONLY',1
    UNION ALL SELECT 'ACADEMY','AC5',NULL,'GROUP_CODE',0.970,'ALLOW',1
    UNION ALL SELECT 'PARKING','PK6',NULL,'GROUP_CODE',0.960,'ALLOW',1
    UNION ALL SELECT 'SUBWAY','SW8',NULL,'GROUP_CODE',0.990,'ALLOW',1
    UNION ALL SELECT 'ACCOMMODATION','AD5',NULL,'GROUP_CODE',0.960,'ALLOW',1
    UNION ALL SELECT 'RESTAURANT','FD6',NULL,'GROUP_CODE',0.950,'ALLOW',10
    UNION ALL SELECT 'CAFE','CE7',NULL,'GROUP_CODE',0.990,'ALLOW',1
    UNION ALL SELECT 'PHARMACY','PM9',NULL,'GROUP_CODE',0.995,'ALLOW',1
) x
JOIN moca.merchant_categories mc ON mc.category_code=x.category_code;

-- OL7은 주유소/충전소를 반드시 분리
INSERT INTO moca.kakao_category_maps
(kakao_category_map_id, merchant_category_id, kakao_category_group_code,
 kakao_category_name_pattern, match_method, confidence_score,
 benefit_match_policy, priority, enabled, created_at, updated_at)
SELECT UUID(), mc.merchant_category_id, 'OL7', x.pattern_name,
       'GROUP_AND_PATTERN', x.confidence_score, 'ALLOW',
       x.priority, TRUE, CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)
FROM (
    SELECT 'FUEL' category_code, '주유소' pattern_name, 0.970 confidence_score, 1 priority
    UNION ALL SELECT 'EV_CHARGING', '전기차 충전소', 0.970, 2
    UNION ALL SELECT 'EV_CHARGING', '충전소', 0.900, 3
) x
JOIN moca.merchant_categories mc ON mc.category_code=x.category_code;

