-- -----------------------------------------------------------------------------
-- 3) 현대카드Z work Edition2의 "대중교통"을 전체 TRANSPORTATION으로 잡지 않음
--    원문이 시내버스/지하철/택시이므로 BUS/SUBWAY/TAXI로 명시
-- -----------------------------------------------------------------------------
DELETE t
FROM moca.benefit_rule_targets t
JOIN moca.benefit_rules r ON r.rule_id=t.rule_id
JOIN moca.benefit_offers o ON o.offer_id=r.offer_id
JOIN moca.card_benefits b ON b.benefit_id=o.benefit_id
JOIN moca.card_content_versions cv ON cv.content_version_id=b.content_version_id
JOIN moca.cards c ON c.card_id=cv.card_id
WHERE c.gorilla_card_id='2680'
  AND o.offer_name='대중교통 10% 청구 할인'
  AND t.target_type='merchant_category';

INSERT INTO moca.benefit_rule_targets
(target_id, rule_id, condition_group, match_mode, target_type,
 merchant_category_id, merchant_id, target_code, target_name,
 target_source, target_authority, minimum_place_confidence, created_at, updated_at)
SELECT UUID(), r.rule_id, 1, 'include', 'merchant_category',
       mc.merchant_category_id, NULL, mc.category_code, mc.category_name,
       'CARD_BENEFIT_EXPLICIT', 'ISSUER_CATEGORY', 0.900,
       CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)
FROM moca.cards c
JOIN moca.card_content_versions cv ON cv.card_id=c.card_id
JOIN moca.card_benefits b ON b.content_version_id=cv.content_version_id
JOIN moca.benefit_offers o ON o.benefit_id=b.benefit_id
JOIN moca.benefit_rules r ON r.offer_id=o.offer_id
JOIN moca.merchant_categories mc
  ON mc.category_code IN ('BUS','SUBWAY','TAXI')
WHERE c.gorilla_card_id='2680'
  AND o.offer_name='대중교통 10% 청구 할인'
  AND NOT EXISTS (
      SELECT 1 FROM moca.benefit_rule_targets t
      WHERE t.rule_id=r.rule_id
        AND t.target_type='merchant_category'
        AND t.merchant_category_id=mc.merchant_category_id
        AND t.match_mode='include'
  );

-- source category 52(대중교통)는 TRANSPORTATION 전체가 아니라 PUBLIC_TRANSIT으로 교정
DELETE gm
FROM moca.card_gorilla_category_maps gm
JOIN moca.merchant_categories mc ON mc.merchant_category_id=gm.merchant_category_id
WHERE gm.source_category_id=52
  AND mc.category_code='TRANSPORTATION';

INSERT INTO moca.card_gorilla_category_maps
(card_gorilla_category_map_id, source_category_id, merchant_category_id,
 priority, enabled, created_at, updated_at)
SELECT UUID(), 52, mc.merchant_category_id, 1, TRUE,
       CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)
FROM moca.merchant_categories mc
WHERE mc.category_code='PUBLIC_TRANSIT'
  AND NOT EXISTS (
      SELECT 1
      FROM moca.card_gorilla_category_maps gm
      WHERE gm.source_category_id=52
        AND gm.merchant_category_id=mc.merchant_category_id
  );

DELETE target
FROM moca.benefit_rule_targets target
JOIN moca.benefit_rules rule ON rule.rule_id=target.rule_id
JOIN moca.benefit_offers offer ON offer.offer_id=rule.offer_id
JOIN moca.card_benefits benefit ON benefit.benefit_id=offer.benefit_id
JOIN moca.merchant_categories category
  ON category.merchant_category_id=target.merchant_category_id
WHERE benefit.source_category_id=52
  AND target.target_type='merchant_category'
  AND category.category_code='TRANSPORTATION';

INSERT INTO moca.benefit_rule_targets
(target_id, rule_id, condition_group, match_mode, target_type,
 merchant_category_id, merchant_id, target_code, target_name,
 target_source, target_authority, minimum_place_confidence, created_at, updated_at)
SELECT UUID(), rule.rule_id, 1, 'include', 'merchant_category',
       category.merchant_category_id, NULL, category.category_code, category.category_name,
       'CARD_GORILLA_CATEGORY', 'ISSUER_CATEGORY', 0.900,
       CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)
FROM moca.card_benefits benefit
JOIN moca.benefit_offers offer ON offer.benefit_id=benefit.benefit_id
JOIN moca.benefit_rules rule ON rule.offer_id=offer.offer_id
JOIN moca.merchant_categories category ON category.category_code='PUBLIC_TRANSIT'
WHERE benefit.source_category_id=52
  AND NOT EXISTS (
      SELECT 1 FROM moca.benefit_rule_targets target
      WHERE target.rule_id=rule.rule_id
        AND target.condition_group=1
        AND target.match_mode='include'
        AND target.target_type='merchant_category'
        AND target.merchant_category_id=category.merchant_category_id
  );

-- -----------------------------------------------------------------------------
-- 4) 가맹점 마스터 생성 뒤 명시 target 재조정
--    첫 seed 실행에서도 Z work·무신사·SOL Plan target이 빠지지 않도록 한다.
-- -----------------------------------------------------------------------------
DELETE target
FROM moca.benefit_rule_targets target
JOIN moca.benefit_rules rule_data ON rule_data.rule_id=target.rule_id
JOIN moca.benefit_offers offer ON offer.offer_id=rule_data.offer_id
JOIN moca.card_benefits benefit ON benefit.benefit_id=offer.benefit_id
JOIN moca.card_content_versions version ON version.content_version_id=benefit.content_version_id
JOIN moca.cards card ON card.card_id=version.card_id
WHERE card.gorilla_card_id='2680'
  AND offer.offer_name IN ('편의점 10% 청구 할인', '커피전문점 10% 청구 할인')
  AND target.target_type='merchant_category';

CREATE TEMPORARY TABLE seed_appended_card_targets (
    gorilla_card_id VARCHAR(50) NOT NULL,
    offer_name VARCHAR(255) NOT NULL,
    condition_group SMALLINT UNSIGNED NOT NULL,
    match_mode VARCHAR(10) NOT NULL,
    target_type VARCHAR(30) NOT NULL,
    target_code VARCHAR(100) NOT NULL,
    target_name VARCHAR(255) NOT NULL
) ENGINE=InnoDB;

