INSERT INTO moca.benefit_rule_targets
(target_id, rule_id, condition_group, match_mode, target_type,
 merchant_category_id, merchant_id, target_code, target_name,
 target_source, target_authority, minimum_place_confidence, created_at, updated_at)
SELECT UUID(), r.rule_id, x.condition_group, x.match_mode, x.target_type,
       mc.merchant_category_id, m.merchant_id, x.target_code, x.target_name,
       'CARD_BENEFIT_EXPLICIT',
       CASE x.target_type
           WHEN 'merchant_category' THEN 'ISSUER_CATEGORY'
           WHEN 'merchant' THEN 'MERCHANT_EXACT'
           ELSE 'ALL_MERCHANTS'
       END,
       CASE x.target_type WHEN 'all_merchants' THEN 0.000 ELSE 0.990 END,
       CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)
FROM seed_appended_card_targets x
JOIN moca.cards c ON c.gorilla_card_id=x.gorilla_card_id
JOIN moca.card_content_versions cv ON cv.card_id=c.card_id
JOIN moca.card_benefits b ON b.content_version_id=cv.content_version_id
JOIN moca.benefit_offers o ON o.benefit_id=b.benefit_id AND o.offer_name=x.offer_name
JOIN moca.benefit_rules r ON r.offer_id=o.offer_id
LEFT JOIN moca.merchant_categories mc
  ON x.target_type='merchant_category' AND mc.category_code=x.target_code
LEFT JOIN moca.merchants m
  ON x.target_type='merchant' AND (m.normalized_name=x.target_code OR m.name=x.target_code)
WHERE (x.target_type='all_merchants'
       OR (x.target_type='merchant_category' AND mc.merchant_category_id IS NOT NULL)
       OR (x.target_type='merchant' AND m.merchant_id IS NOT NULL))
  AND NOT EXISTS (
      SELECT 1 FROM moca.benefit_rule_targets t
      WHERE t.rule_id=r.rule_id
        AND t.condition_group=x.condition_group
        AND t.match_mode=x.match_mode
        AND t.target_type=x.target_type
        AND t.target_code=x.target_code
  );

UPDATE moca.benefit_rule_targets t
JOIN moca.benefit_rules r ON r.rule_id=t.rule_id
JOIN moca.benefit_offers o ON o.offer_id=r.offer_id
JOIN moca.card_benefits b ON b.benefit_id=o.benefit_id
JOIN moca.card_content_versions cv ON cv.content_version_id=b.content_version_id
JOIN moca.cards c ON c.card_id=cv.card_id
JOIN seed_appended_card_targets x
  ON x.gorilla_card_id=c.gorilla_card_id
 AND x.offer_name=o.offer_name
 AND x.match_mode=t.match_mode
 AND x.target_type=t.target_type
 AND x.target_code=t.target_code
SET t.condition_group=x.condition_group;

DROP TEMPORARY TABLE seed_appended_card_targets;

-- -----------------------------------------------------------------------------
-- 5) 의료 scope는 별도 runtime 로직이 아니라 benefit_rule_targets에 통합
--    exclude가 include보다 우선한다.
-- -----------------------------------------------------------------------------
INSERT INTO moca.benefit_rule_targets
(target_id, rule_id, condition_group, match_mode, target_type,
 merchant_category_id, merchant_id, target_code, target_name,
 target_source, target_authority, minimum_place_confidence, created_at, updated_at)
SELECT UUID(), r.rule_id, 1, s.match_mode, 'merchant_category',
       s.merchant_category_id, NULL,
       mc.category_code, mc.category_name,
       'MEDICAL_SCOPE', 'ISSUER_CATEGORY', 0.900,
       CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)
FROM moca.benefit_medical_scopes s
JOIN moca.merchant_categories mc
  ON mc.merchant_category_id=s.merchant_category_id
JOIN moca.card_benefits b
  ON b.benefit_id=s.benefit_id
JOIN moca.benefit_offers o
  ON o.benefit_id=b.benefit_id
JOIN moca.benefit_rules r
  ON r.offer_id=o.offer_id
WHERE NOT EXISTS (
    SELECT 1 FROM moca.benefit_rule_targets t
    WHERE t.rule_id=r.rule_id
      AND t.match_mode=s.match_mode
      AND t.target_type='merchant_category'
      AND t.merchant_category_id=s.merchant_category_id
);

-- -----------------------------------------------------------------------------
-- 6) 기존 문자열 target을 FK로 backfill. 이후 계산 코드는 FK만 사용.
-- -----------------------------------------------------------------------------
UPDATE moca.benefit_rule_targets t
JOIN moca.merchant_categories mc
  ON mc.category_code=t.target_code
SET t.merchant_category_id=mc.merchant_category_id,
    t.merchant_id=NULL,
    t.target_source=CASE
        WHEN t.target_source='LEGACY' THEN 'CARD_GORILLA_CATEGORY'
        ELSE t.target_source
    END,
    t.target_authority='ISSUER_CATEGORY',
    t.minimum_place_confidence=CASE
        WHEN t.minimum_place_confidence < 0.850 THEN 0.850
        ELSE t.minimum_place_confidence
    END
WHERE t.target_type='merchant_category'
  AND t.merchant_category_id IS NULL;

UPDATE moca.benefit_rule_targets t
JOIN moca.merchants m
  ON m.normalized_name=t.target_code OR m.name=t.target_code
SET t.merchant_id=m.merchant_id,
    t.merchant_category_id=NULL,
    t.target_source='MERCHANT_EXPLICIT',
    t.target_authority='MERCHANT_EXACT',
    t.minimum_place_confidence=0.950
WHERE t.target_type='merchant'
  AND t.merchant_id IS NULL;

UPDATE moca.benefit_rule_targets
SET merchant_category_id=NULL,
    merchant_id=NULL,
    target_source='ALL_MERCHANTS',
    target_authority='ALL_MERCHANTS',
    minimum_place_confidence=0.000
WHERE target_type='all_merchants';

DELETE duplicate_target
FROM moca.benefit_rule_targets duplicate_target
JOIN moca.benefit_rule_targets keeper
  ON keeper.rule_id=duplicate_target.rule_id
 AND keeper.condition_group=duplicate_target.condition_group
 AND keeper.match_mode=duplicate_target.match_mode
 AND keeper.target_type=duplicate_target.target_type
 AND keeper.target_code=duplicate_target.target_code
 AND keeper.target_id < duplicate_target.target_id;

-- -----------------------------------------------------------------------------
-- 7) FK 변환 결과 검증
-- -----------------------------------------------------------------------------
CREATE TEMPORARY TABLE moca.seed_target_integrity_guard (
    unresolved_count INT NOT NULL,
    CONSTRAINT chk_seed_target_integrity CHECK (unresolved_count = 0)
) ENGINE=InnoDB;

INSERT INTO moca.seed_target_integrity_guard (unresolved_count)
SELECT COUNT(*)
FROM moca.benefit_rule_targets t
WHERE (t.target_type='merchant_category'
       AND (t.merchant_category_id IS NULL OR t.merchant_id IS NOT NULL))
   OR (t.target_type='merchant'
       AND (t.merchant_id IS NULL OR t.merchant_category_id IS NOT NULL))
   OR (t.target_type='all_merchants'
       AND (t.merchant_category_id IS NOT NULL OR t.merchant_id IS NOT NULL))
   OR (t.target_type NOT IN ('merchant_category','merchant','all_merchants')
       AND (t.merchant_category_id IS NOT NULL OR t.merchant_id IS NOT NULL));

DROP TEMPORARY TABLE moca.seed_target_integrity_guard;
DROP TEMPORARY TABLE moca.benefit_medical_scopes;

COMMIT;
SET SESSION sql_mode = @MOCA_OLD_SQL_MODE;


