SET cv.main_benefits =
    '쿠팡 최대 4만원 적립(최대 4%: 기본2%+추가2%), 쿠팡 외 최대 2.4만원 적립(최대2.4%: 기본0.2%+추가2.2%), [프로모션 기간: ~26.10.15]'
WHERE c.gorilla_card_id = '2609'
  AND cv.name = '쿠팡 와우카드';

UPDATE card_content_versions cv
JOIN cards c ON c.card_id = cv.card_id
SET cv.main_benefits =
    '커피, 모바일, 문화 10% 할인, 뷰티, 편의점 5% 할인, KB Pay 2% 추가 할인'
WHERE c.gorilla_card_id = '2422'
  AND cv.name = '노리2 체크카드(KB Pay)';

