('테마파크','에버랜드·롯데월드 15,000원 할인','discount','fixed_amount',15000,'KRW',200000,30000,15000,1,'merchant','롯데월드','롯데월드',2);

INSERT INTO moca.benefit_offers
    (offer_id, benefit_id, offer_name, position, reward_type, value_type,
     calculation_mode, calculation_basis, stacking_mode, valuation_scope, valuation_method)
SELECT UUID(), benefit.benefit_id, seed.offer_name, 2, seed.reward_type, seed.value_type,
       CASE seed.value_type WHEN 'fixed_amount' THEN 'single_tier' ELSE 'flat' END,
       'transaction_amount', 'standalone', 'transaction', 'direct'
FROM (SELECT DISTINCT benefit_title, offer_name, reward_type, value_type
      FROM seed_nori2_offline_benefits) seed
JOIN moca.cards card ON card.gorilla_card_id='2422'
JOIN moca.card_content_versions version ON version.card_id=card.card_id
JOIN moca.card_benefits benefit ON benefit.content_version_id=version.content_version_id
  AND benefit.title=seed.benefit_title
WHERE NOT EXISTS (
    SELECT 1 FROM moca.benefit_offers existing
    WHERE existing.benefit_id=benefit.benefit_id AND existing.offer_name=seed.offer_name
);

INSERT INTO moca.benefit_rules
    (rule_id, offer_id, position, rule_effect, stacking_mode, reward_value, reward_unit,
     previous_spend_min_krw, transaction_min_krw, rule_schema_version,
     rule_support_status, rule_definition_json)
SELECT UUID(), offer.offer_id, 1, 'grant', 'standalone', seed.reward_value, seed.reward_unit,
       seed.previous_spend_min_krw, seed.transaction_min_krw, 1, 'SUPPORTED',
       JSON_OBJECT(
           'schemaVersion', 1,
           'conditions', JSON_OBJECT('all', JSON_ARRAY(), 'any', JSON_ARRAY(), 'none', JSON_ARRAY()),
           'reward', JSON_OBJECT(
               'benefitType', 'DISCOUNT',
               'rewardUnit', CASE WHEN seed.value_type='fixed_amount' THEN 'KRW' ELSE 'KRW' END,
               'calculation', CASE WHEN seed.value_type='fixed_amount' THEN 'FIXED' ELSE 'RATE' END,
               'rate', CASE WHEN seed.value_type='fixed_amount' THEN '0' ELSE CAST(seed.reward_value / 100 AS CHAR) END,
               'value', CASE WHEN seed.value_type='fixed_amount' THEN CAST(seed.reward_value AS CHAR) ELSE '0' END,
               'spendUnitAmount', '0'
           ),
           'limits', JSON_MERGE_PRESERVE(
               JSON_ARRAY(),
               CASE WHEN seed.monthly_usage_count IS NOT NULL
                    THEN JSON_ARRAY(JSON_OBJECT('type', 'MONTHLY_USAGE_COUNT', 'value', CAST(seed.monthly_usage_count AS CHAR)))
                    ELSE JSON_ARRAY() END
           )
       )
FROM (SELECT DISTINCT benefit_title, offer_name, reward_type, value_type, reward_value,
             reward_unit, previous_spend_min_krw, transaction_min_krw, monthly_usage_count
      FROM seed_nori2_offline_benefits) seed
JOIN moca.cards card ON card.gorilla_card_id='2422'
JOIN moca.card_content_versions version ON version.card_id=card.card_id
JOIN moca.card_benefits benefit ON benefit.content_version_id=version.content_version_id
  AND benefit.title=seed.benefit_title
JOIN moca.benefit_offers offer ON offer.benefit_id=benefit.benefit_id AND offer.offer_name=seed.offer_name
WHERE NOT EXISTS (SELECT 1 FROM moca.benefit_rules existing WHERE existing.offer_id=offer.offer_id);

INSERT INTO moca.benefit_rule_targets
    (target_id, rule_id, condition_group, match_mode, target_type,
     merchant_category_id, merchant_id, target_code, target_name,
     target_source, target_authority, minimum_place_confidence, created_at, updated_at)
SELECT UUID(), rule_data.rule_id, seed.condition_group, 'include', seed.target_type,
       category.merchant_category_id, merchant.merchant_id, seed.target_code, seed.target_name,
       'CARD_BENEFIT_EXPLICIT', CASE seed.target_type WHEN 'merchant' THEN 'MERCHANT_EXACT' ELSE 'ISSUER_CATEGORY' END,
       0.990, CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)
FROM seed_nori2_offline_benefits seed
JOIN moca.cards card ON card.gorilla_card_id='2422'
JOIN moca.card_content_versions version ON version.card_id=card.card_id
JOIN moca.card_benefits benefit ON benefit.content_version_id=version.content_version_id AND benefit.title=seed.benefit_title
JOIN moca.benefit_offers offer ON offer.benefit_id=benefit.benefit_id AND offer.offer_name=seed.offer_name
JOIN moca.benefit_rules rule_data ON rule_data.offer_id=offer.offer_id
LEFT JOIN moca.merchant_categories category ON seed.target_type='merchant_category' AND category.category_code=seed.target_code
LEFT JOIN moca.merchants merchant ON seed.target_type='merchant' AND merchant.normalized_name=seed.target_code
WHERE NOT EXISTS (
    SELECT 1 FROM moca.benefit_rule_targets existing
    WHERE existing.rule_id=rule_data.rule_id AND existing.target_type=seed.target_type
      AND existing.target_code=seed.target_code
)
  AND ((seed.target_type='merchant' AND merchant.merchant_id IS NOT NULL)
       OR (seed.target_type='merchant_category' AND category.merchant_category_id IS NOT NULL));

INSERT INTO moca.benefit_limit_policies
    (limit_policy_id, offer_id, policy_name, limit_period, limit_type, limit_unit, shared_group_key)
SELECT UUID(), offer.offer_id, '노리2 월간 통합할인한도', 'monthly', 'reward_amount', 'KRW', 'NORI2_MONTHLY_TOTAL'
FROM moca.benefit_offers offer
JOIN moca.card_benefits benefit ON benefit.benefit_id=offer.benefit_id
JOIN moca.card_content_versions version ON version.content_version_id=benefit.content_version_id
JOIN moca.cards card ON card.card_id=version.card_id
WHERE card.gorilla_card_id='2422'
  AND offer.offer_name IN ('스타벅스·커피빈 10% 할인','올리브영·미용실 5% 할인','GS25·CU 5% 할인','CGV 4,000원 할인','에버랜드·롯데월드 15,000원 할인')
  AND NOT EXISTS (SELECT 1 FROM moca.benefit_limit_policies existing WHERE existing.offer_id=offer.offer_id AND existing.shared_group_key='NORI2_MONTHLY_TOTAL');

INSERT INTO moca.benefit_limit_tiers
    (limit_tier_id, limit_policy_id, position, limit_value, previous_spend_min_krw)
SELECT UUID(), policy.limit_policy_id, tiers.position, tiers.limit_value, tiers.previous_spend_min_krw
FROM moca.benefit_limit_policies policy
JOIN moca.benefit_offers offer ON offer.offer_id=policy.offer_id
JOIN moca.card_benefits benefit ON benefit.benefit_id=offer.benefit_id
JOIN moca.card_content_versions version ON version.content_version_id=benefit.content_version_id
JOIN moca.cards card ON card.card_id=version.card_id
CROSS JOIN (SELECT 1 position,20000 limit_value,200000 previous_spend_min_krw UNION ALL SELECT 2,30000,400000 UNION ALL SELECT 3,40000,600000 UNION ALL SELECT 4,50000,800000) tiers
WHERE card.gorilla_card_id='2422' AND policy.shared_group_key='NORI2_MONTHLY_TOTAL'
  AND NOT EXISTS (SELECT 1 FROM moca.benefit_limit_tiers existing WHERE existing.limit_policy_id=policy.limit_policy_id AND existing.position=tiers.position);

-- 카페 혜택은 전월 실적 조건이 없으므로 통합 실적 tier와 분리해 월 3,000원 한도를 적용한다.
INSERT INTO moca.benefit_limit_policies
    (limit_policy_id, offer_id, policy_name, limit_period, limit_type, limit_unit, shared_group_key)
SELECT UUID(), offer.offer_id, '노리2 카페 월 할인한도', 'monthly', 'reward_amount', 'KRW', 'NORI2_CAFE_MONTHLY'
FROM moca.benefit_offers offer
JOIN moca.card_benefits benefit ON benefit.benefit_id=offer.benefit_id
JOIN moca.card_content_versions version ON version.content_version_id=benefit.content_version_id
JOIN moca.cards card ON card.card_id=version.card_id
WHERE card.gorilla_card_id='2422'
  AND offer.offer_name='스타벅스·커피빈 10% 할인'
  AND NOT EXISTS (SELECT 1 FROM moca.benefit_limit_policies existing WHERE existing.offer_id=offer.offer_id AND existing.shared_group_key='NORI2_CAFE_MONTHLY');

INSERT INTO moca.benefit_limit_tiers
    (limit_tier_id, limit_policy_id, position, limit_value, previous_spend_min_krw)
SELECT UUID(), policy.limit_policy_id, 1, 3000, NULL
FROM moca.benefit_limit_policies policy
JOIN moca.benefit_offers offer ON offer.offer_id=policy.offer_id
WHERE policy.shared_group_key='NORI2_CAFE_MONTHLY'
  AND offer.offer_name='스타벅스·커피빈 10% 할인'
  AND NOT EXISTS (SELECT 1 FROM moca.benefit_limit_tiers existing WHERE existing.limit_policy_id=policy.limit_policy_id AND existing.position=1);

DROP TEMPORARY TABLE seed_nori2_offline_benefits;

-- issuer canonical configuration checks
SELECT 'ISSUER_CONFIG_MISMATCH' AS error_type, i.issuer_id, i.issuer_name
FROM issuers i
JOIN (
    SELECT 'd117c8af-f64f-5cf7-9e63-d5e2b1c79df9' issuer_id, '0301' institution_code, 'KB카드' issuer_name,
           TRUE requires_id, TRUE requires_password, FALSE requires_card_no,
           FALSE requires_card_password, FALSE requires_birth_date, 11 performance_lookback_months
    UNION ALL SELECT '6b9cc0be-0b82-59e4-b206-9bd0e738869a','0302','현대카드',TRUE,TRUE,TRUE,TRUE,TRUE,1
    UNION ALL SELECT 'e8d88129-2397-5c26-9539-d6deef1e7a2c','0303','삼성카드',TRUE,TRUE,FALSE,FALSE,FALSE,NULL
    UNION ALL SELECT 'c5fc7641-283e-57ec-ac5a-66652b93ca82','0304','NH카드',TRUE,TRUE,TRUE,TRUE,TRUE,1
    UNION ALL SELECT 'ea83ae28-f017-5fad-ac7b-c68e01a5fc10','0305','BC카드',TRUE,TRUE,FALSE,FALSE,FALSE,1
    UNION ALL SELECT '05c1fd94-4fd2-50e4-9a52-6b0cfc6a4fef','0306','신한카드',TRUE,TRUE,FALSE,FALSE,FALSE,0
    UNION ALL SELECT 'e86afcc7-0f12-5343-b208-a0d9f188a866','0309','우리카드',TRUE,TRUE,FALSE,FALSE,FALSE,2
    UNION ALL SELECT '194b143e-b0c0-54a4-9098-c11172eeaccd','0311','롯데카드',TRUE,TRUE,FALSE,FALSE,FALSE,1
    UNION ALL SELECT '672bf9fa-fd68-5daa-a471-44705608fff7','0313','하나카드',TRUE,TRUE,FALSE,FALSE,FALSE,11
) expected ON expected.issuer_id=i.issuer_id
WHERE i.institution_code <> expected.institution_code
   OR i.issuer_name <> expected.issuer_name
   OR i.requires_id <> expected.requires_id
   OR i.requires_password <> expected.requires_password
   OR i.requires_card_no <> expected.requires_card_no
   OR i.requires_card_password <> expected.requires_card_password
   OR i.requires_birth_date <> expected.requires_birth_date
   OR NOT (i.performance_lookback_months <=> expected.performance_lookback_months);

-- duplicate card identity
SELECT 'DUPLICATE_GORILLA_CARD_ID' AS error_type, gorilla_card_id, COUNT(*) AS cnt
FROM cards
WHERE gorilla_card_id IS NOT NULL
GROUP BY gorilla_card_id
HAVING COUNT(*) > 1;

-- duplicate 2422 option groups
SELECT 'DUPLICATE_2422_OPTION_GROUP' AS error_type, c.gorilla_card_id, g.group_key, COUNT(*) AS cnt
FROM card_option_groups g
JOIN cards c ON c.card_id = g.card_id
WHERE c.gorilla_card_id = '2422'
GROUP BY c.gorilla_card_id, g.group_key
HAVING COUNT(*) > 1;

-- duplicate 2422 option choices
SELECT 'DUPLICATE_2422_OPTION_CHOICE' AS error_type, g.option_group_id, oc.choice_key, COUNT(*) AS cnt
FROM card_option_choices oc
JOIN card_option_groups g ON g.option_group_id = oc.option_group_id
JOIN cards c ON c.card_id = g.card_id
WHERE c.gorilla_card_id = '2422'
GROUP BY g.option_group_id, oc.choice_key
HAVING COUNT(*) > 1;

-- critical issuers
SELECT 'CARD_2609_ISSUER_MISMATCH' AS error_type, c.gorilla_card_id, i.issuer_name
FROM cards c
JOIN issuers i ON i.issuer_id = c.issuer_id
WHERE c.gorilla_card_id = '2609'
  AND i.issuer_name <> 'KB카드';

SELECT 'CARD_2422_ISSUER_MISMATCH' AS error_type, c.gorilla_card_id, i.issuer_name
FROM cards c
JOIN issuers i ON i.issuer_id = c.issuer_id
WHERE c.gorilla_card_id = '2422'
  AND i.issuer_name <> 'KB카드';

-- required option rows must exist exactly once
SELECT 'MISSING_2422_OPTION_GROUP' AS error_type
WHERE NOT EXISTS (
    SELECT 1
    FROM card_option_groups g
    JOIN cards c ON c.card_id = g.card_id
    WHERE c.gorilla_card_id = '2422'
      AND g.group_key = 'main'
);

SELECT 'MISSING_2422_OPTION_A' AS error_type
WHERE NOT EXISTS (
    SELECT 1
    FROM card_option_choices oc
    JOIN card_option_groups g ON g.option_group_id = oc.option_group_id
    JOIN cards c ON c.card_id = g.card_id
    WHERE c.gorilla_card_id = '2422'
      AND g.group_key = 'main'
      AND oc.choice_key = 'a'
);

SELECT 'MISSING_2422_OPTION_B' AS error_type
WHERE NOT EXISTS (
    SELECT 1
    FROM card_option_choices oc
    JOIN card_option_groups g ON g.option_group_id = oc.option_group_id
    JOIN cards c ON c.card_id = g.card_id
    WHERE c.gorilla_card_id = '2422'
      AND g.group_key = 'main'
      AND oc.choice_key = 'b'
);

-- =================================================================================
-- JSON BENEFIT RULE DEFINITIONS (schema version 1)
-- Flyway V22가 기존 데이터에 수행하는 보정을 seed 후 생성되는 카드에도 동일하게 적용한다.
-- 관계형 benefit_rule_targets는 후보 가맹점 필터로 계속 사용한다.
-- =================================================================================
UPDATE moca.benefit_rules rule_data
JOIN moca.benefit_offers offer ON offer.offer_id = rule_data.offer_id
JOIN moca.card_benefits benefit ON benefit.benefit_id = offer.benefit_id
JOIN moca.card_content_versions version ON version.content_version_id = benefit.content_version_id
JOIN moca.cards card ON card.card_id = version.card_id
SET rule_data.rule_schema_version = 1,
    rule_data.rule_support_status = 'SUPPORTED',
    rule_data.rule_definition_json = JSON_OBJECT(
        'schemaVersion', 1,
        'conditions', JSON_OBJECT(
            'all', JSON_ARRAY(
                JSON_OBJECT(
                    'type', 'PREVIOUS_MONTH_SPEND',
                    'operator', 'GTE',
                    'value', CAST(rule_data.previous_spend_min_krw AS CHAR),
                    'rejectionReason', 'PERFORMANCE_NOT_MET'
                )
            ),
            'any', JSON_ARRAY(),
            'none', JSON_ARRAY()
        ),
        'reward', JSON_OBJECT(
            'benefitType', 'DISCOUNT',
            'rewardUnit', 'KRW',
            'calculation', 'RATE',
            'rate', CAST(rule_data.reward_value / 100 AS CHAR)
        ),
        'limits', JSON_ARRAY(
            JSON_OBJECT('type', 'DAILY_USAGE_COUNT', 'value', '1')
        )
    )
WHERE card.gorilla_card_id = '2680'
  AND offer.offer_name IN (
      '온라인 쇼핑 10% 청구 할인',
      '편의점 10% 청구 할인',
      '커피전문점 10% 청구 할인',
      '도서 10% 청구 할인'
  );

-- 공식 안내는 온라인 채널이 아니라 무신사·솔드아웃 가맹점 승인을 할인 기준으로 둔다.
UPDATE moca.benefit_rules rule_data
JOIN moca.benefit_offers offer ON offer.offer_id = rule_data.offer_id
JOIN moca.card_benefits benefit ON benefit.benefit_id = offer.benefit_id
JOIN moca.card_content_versions version ON version.content_version_id = benefit.content_version_id
JOIN moca.cards card ON card.card_id = version.card_id
SET rule_data.rule_schema_version = 1,
    rule_data.rule_support_status = 'SUPPORTED',
    rule_data.rule_definition_json = JSON_OBJECT(
        'schemaVersion', 1,
        'conditions', JSON_OBJECT(
            'all', JSON_ARRAY(
                JSON_OBJECT('type', 'PREVIOUS_MONTH_SPEND', 'operator', 'GTE',
                            'value', '300000', 'rejectionReason', 'PERFORMANCE_NOT_MET')
            ),
            'any', JSON_ARRAY(),
            'none', JSON_ARRAY()
        ),
        'reward', JSON_OBJECT(
            'benefitType', 'DISCOUNT', 'rewardUnit', 'KRW',
            'calculation', 'RATE', 'rate', '0.05'
        ),
        'limits', JSON_ARRAY()
    )
WHERE card.gorilla_card_id = '733'
  AND offer.offer_name = '무신사/솔드아웃 5% 할인';

-- 노리2 체크카드의 온라인·자동이체 혜택은 카드 설명에는 표시하되,
-- 현재 오프라인 승인 기반 계산 범위에서는 정보 전용으로 유지한다.
UPDATE moca.benefit_rules rule_data
JOIN moca.benefit_offers offer ON offer.offer_id = rule_data.offer_id
JOIN moca.card_benefits benefit ON benefit.benefit_id = offer.benefit_id
JOIN moca.card_content_versions version ON version.content_version_id = benefit.content_version_id
JOIN moca.cards card ON card.card_id = version.card_id
SET rule_data.rule_schema_version = 1,
    rule_data.rule_support_status = 'INFORMATION_ONLY',
    rule_data.rule_definition_json = JSON_OBJECT(
        'schemaVersion', 1,
        'mode', 'INFORMATION_ONLY',
        'reason', 'ONLINE_OR_AUTOPAY_CALCULATION_OUT_OF_SCOPE'
    )
WHERE card.gorilla_card_id = '2422'
  AND offer.offer_name IN (
      '구글플레이스토어·앱스토어 10% 할인',
      '인터파크 티켓 10% 할인',
      '넷플릭스·유튜브 프리미엄 1,000원 할인',
      '배달의민족·요기요 1,000원 할인',
      '통신요금 2,500원 할인'
  );

UPDATE moca.benefit_rules rule_data
JOIN moca.benefit_offers offer ON offer.offer_id = rule_data.offer_id
JOIN moca.card_benefits benefit ON benefit.benefit_id = offer.benefit_id
JOIN moca.card_content_versions version ON version.content_version_id = benefit.content_version_id
JOIN moca.cards card ON card.card_id = version.card_id
SET rule_data.rule_schema_version = 1,
    rule_data.rule_support_status = 'PARTIAL',
    rule_data.rule_definition_json = JSON_OBJECT(
        'schemaVersion', 1,
        'conditions', JSON_OBJECT(
            'all', JSON_ARRAY(
                JSON_OBJECT('type', 'PREVIOUS_MONTH_SPEND', 'operator', 'GTE',
                            'value', '400000', 'rejectionReason', 'PERFORMANCE_NOT_MET'),
                JSON_OBJECT('type', 'PREVIOUS_MONTH_SPEND', 'operator', 'LT',
                            'value', '1000000', 'rejectionReason', 'PERFORMANCE_NOT_MET')
            ),
            'any', JSON_ARRAY(),
            'none', JSON_ARRAY()
        ),
        'reward', JSON_OBJECT(
            'benefitType', 'POINT', 'rewardUnit', 'POINT',
            'calculation', 'RATE', 'rate', '0.01'
        ),
        'limits', JSON_ARRAY()
    )
WHERE card.gorilla_card_id = '2899'
  AND offer.offer_name = '국내/외 전가맹점 기본 적립'
  AND rule_data.position = 1;

UPDATE moca.benefit_rules rule_data
JOIN moca.benefit_offers offer ON offer.offer_id = rule_data.offer_id
JOIN moca.card_benefits benefit ON benefit.benefit_id = offer.benefit_id
JOIN moca.card_content_versions version ON version.content_version_id = benefit.content_version_id
JOIN moca.cards card ON card.card_id = version.card_id
SET rule_data.rule_schema_version = 1,
    rule_data.rule_support_status = 'PARTIAL',
    rule_data.rule_definition_json = JSON_OBJECT(
        'schemaVersion', 1,
        'conditions', JSON_OBJECT(
            'all', JSON_ARRAY(
                JSON_OBJECT('type', 'PREVIOUS_MONTH_SPEND', 'operator', 'GTE',
                            'value', '1000000', 'rejectionReason', 'PERFORMANCE_NOT_MET')
            ),
            'any', JSON_ARRAY(),
            'none', JSON_ARRAY()
        ),
        'reward', JSON_OBJECT(
            'benefitType', 'POINT', 'rewardUnit', 'POINT',
            'calculation', 'RATE', 'rate', '0.015'
        ),
        'limits', JSON_ARRAY()
    )
WHERE card.gorilla_card_id = '2899'
  AND offer.offer_name = '국내/외 전가맹점 기본 적립'
  AND rule_data.position = 2;

-- =================================================================================
-- FLAT CATEGORY / MERCHANT MASTER / BENEFIT STRUCTURING AUDIT
-- V23은 운영 기존 데이터에 적용되고, 이 블록은 V23 이후 적재되는 seed 데이터에 같은 정책을 적용한다.
-- =================================================================================

CREATE TEMPORARY TABLE seed_category_hierarchy_snapshot AS
SELECT child.merchant_category_id AS child_category_id,
       child.category_code AS child_category_code,
       child.category_name AS child_category_name,
       parent.merchant_category_id AS parent_category_id
FROM moca.merchant_categories child
INNER JOIN moca.merchant_categories parent ON parent.merchant_category_id = child.parent_id;

INSERT INTO moca.benefit_rule_targets
    (target_id, rule_id, condition_group, match_mode, target_type,
     merchant_category_id, merchant_id, target_code, target_name,
     target_source, target_authority, minimum_place_confidence, created_at, updated_at)
SELECT UUID(), target.rule_id, target.condition_group, target.match_mode, 'merchant_category',
       hierarchy.child_category_id, NULL,
       hierarchy.child_category_code, hierarchy.child_category_name,
       target.target_source, target.target_authority, target.minimum_place_confidence,
       CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)
FROM moca.benefit_rule_targets target
INNER JOIN seed_category_hierarchy_snapshot hierarchy
    ON hierarchy.parent_category_id = target.merchant_category_id
WHERE target.target_type = 'merchant_category'
  AND NOT EXISTS (
      SELECT 1 FROM moca.benefit_rule_targets existing_target
      WHERE existing_target.rule_id = target.rule_id
        AND existing_target.condition_group = target.condition_group
        AND existing_target.match_mode = target.match_mode
        AND existing_target.target_type = 'merchant_category'
        AND existing_target.merchant_category_id = hierarchy.child_category_id
  );

INSERT INTO moca.card_gorilla_category_maps
    (card_gorilla_category_map_id, source_category_id, merchant_category_id,
     priority, enabled, created_at, updated_at)
SELECT UUID(), source_map.source_category_id, hierarchy.child_category_id,
       source_map.priority, source_map.enabled, CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)
FROM moca.card_gorilla_category_maps source_map
INNER JOIN seed_category_hierarchy_snapshot hierarchy
    ON hierarchy.parent_category_id = source_map.merchant_category_id
WHERE NOT EXISTS (
    SELECT 1 FROM moca.card_gorilla_category_maps existing_map
    WHERE existing_map.source_category_id = source_map.source_category_id
      AND existing_map.merchant_category_id = hierarchy.child_category_id
);

UPDATE moca.merchant_categories
SET parent_id = NULL,
    updated_at = CURRENT_TIMESTAMP(6)
WHERE parent_id IS NOT NULL;

