INSERT INTO moca.merchants
    (merchant_id, merchant_category_id, name, normalized_name, status,
     has_physical_location, created_at, updated_at)
SELECT UUID(), category.merchant_category_id,
       seed.merchant_name, seed.merchant_name, 'active', seed.has_physical_location,
       CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)
FROM seed_benefit_merchant_master seed
INNER JOIN moca.merchant_categories category ON category.category_code = seed.category_code
WHERE NOT EXISTS (
    SELECT 1 FROM moca.merchants merchant
    WHERE merchant.normalized_name = seed.merchant_name
);

DROP TEMPORARY TABLE seed_benefit_merchant_master;

-- 카드 혜택 원문의 표기 변형은 canonical merchant를 늘리지 않고 alias로 흡수한다.
INSERT INTO moca.merchant_aliases
    (merchant_alias_id, merchant_id, alias_name, normalized_alias_name,
     source_type, match_type, created_at)
SELECT UUID(), merchant.merchant_id, aliases.alias_name,
       aliases.normalized_alias_name, 'benefit_text', 'exact', CURRENT_TIMESTAMP(6)
FROM (
    SELECT 'GS25' canonical_name, 'GS 25' alias_name, 'GS25' normalized_alias_name
    UNION ALL SELECT 'GS25', '지에스25', '지에스25'
    UNION ALL SELECT 'GS25', 'GS리테일 GS25', 'GS리테일GS25'
    UNION ALL SELECT '스타벅스', '스타벅스커피', '스타벅스커피'
    UNION ALL SELECT '스타벅스', '스타벅스 코리아', '스타벅스코리아'
    UNION ALL SELECT '스타벅스', 'STARBUCKS', 'STARBUCKS'
    UNION ALL SELECT 'CGV', '씨지브이', '씨지브이'
    UNION ALL SELECT 'CGV', 'CJ CGV', 'CJCGV'
) aliases
INNER JOIN moca.merchants merchant
    ON merchant.normalized_name = aliases.canonical_name
WHERE NOT EXISTS (
    SELECT 1
    FROM moca.merchant_aliases existing
    WHERE existing.normalized_alias_name = aliases.normalized_alias_name
);

-- KB 틴업 체크카드의 "CU, 세븐일레븐" 혜택은 편의점 전체로 확장하지 않는다.
DELETE target
FROM moca.benefit_rule_targets target
INNER JOIN moca.benefit_rules rule_data ON rule_data.rule_id = target.rule_id
INNER JOIN moca.benefit_offers offer ON offer.offer_id = rule_data.offer_id
INNER JOIN moca.card_benefits benefit ON benefit.benefit_id = offer.benefit_id
INNER JOIN moca.card_content_versions version
    ON version.content_version_id = benefit.content_version_id
INNER JOIN moca.cards card ON card.card_id = version.card_id
WHERE card.gorilla_card_id = '2852'
  AND benefit.title = '편의점'
  AND target.target_type = 'merchant_category';

INSERT INTO moca.benefit_rule_targets
    (target_id, rule_id, condition_group, match_mode, target_type,
     merchant_category_id, merchant_id, target_code, target_name,
     target_source, target_authority, minimum_place_confidence, created_at, updated_at)
SELECT UUID(), rule_data.rule_id, seed.condition_group, 'include', 'merchant',
       NULL, merchant.merchant_id, seed.merchant_name, seed.merchant_name,
       'CARD_BENEFIT_EXPLICIT', 'MERCHANT_EXACT', 0.990,
       CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)
FROM moca.benefit_rules rule_data
INNER JOIN moca.benefit_offers offer ON offer.offer_id = rule_data.offer_id
INNER JOIN moca.card_benefits benefit ON benefit.benefit_id = offer.benefit_id
INNER JOIN moca.card_content_versions version
    ON version.content_version_id = benefit.content_version_id
INNER JOIN moca.cards card ON card.card_id = version.card_id
CROSS JOIN (
    SELECT 1 condition_group, 'CU' merchant_name
    UNION ALL SELECT 2, '세븐일레븐'
) seed
INNER JOIN moca.merchants merchant ON merchant.normalized_name = seed.merchant_name
WHERE card.gorilla_card_id = '2852'
  AND benefit.title = '편의점'
  AND NOT EXISTS (
      SELECT 1 FROM moca.benefit_rule_targets target
      WHERE target.rule_id = rule_data.rule_id
        AND target.match_mode = 'include'
        AND target.target_type = 'merchant'
        AND target.merchant_id = merchant.merchant_id
  );

-- 올바른POINT체크카드: 전월 실적 없는 기본 0.2%와 생활 영역 추가 0.3%를 분리한다.
INSERT INTO moca.benefit_offers
    (offer_id, benefit_id, offer_name, position, priority, reward_type, value_type,
     calculation_mode, calculation_basis, stacking_mode, reward_timing,
     valuation_scope, valuation_method, created_at, updated_at)
SELECT UUID(), benefit.benefit_id, seed.offer_name, seed.position, seed.priority,
       'points', 'percentage', 'flat', 'transaction_amount', 'additive',
       'point_accrual', 'transaction', 'direct', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)
FROM moca.card_benefits benefit
INNER JOIN moca.card_content_versions version
    ON version.content_version_id = benefit.content_version_id
INNER JOIN moca.cards card ON card.card_id = version.card_id
CROSS JOIN (
    SELECT '전 가맹점 기본적립 0.2%' offer_name, 2 position, 100 priority
    UNION ALL SELECT '생활 영역 추가적립 0.3%', 3, 200
) seed
WHERE card.gorilla_card_id = '360'
  AND benefit.title = '모든가맹점'
  AND NOT EXISTS (
      SELECT 1 FROM moca.benefit_offers offer
      WHERE offer.benefit_id = benefit.benefit_id AND offer.position = seed.position
  );

INSERT INTO moca.benefit_rules
    (rule_id, offer_id, position, priority, rule_name, rule_effect, stacking_mode,
     reward_value, reward_unit, previous_spend_min_krw,
     rounding_type, rounding_unit, rule_support_status, created_at, updated_at)
SELECT UUID(), offer.offer_id, 1, offer.priority,
       CASE offer.position
           WHEN 2 THEN '조건 없는 전 가맹점 기본적립'
           ELSE '전월 30만원 이상 생활 영역 추가적립'
       END,
       'grant', 'standalone',
       CASE offer.position WHEN 2 THEN 0.2 ELSE 0.3 END,
       'percent', CASE offer.position WHEN 2 THEN NULL ELSE 300000 END,
       'floor', 1, 'SUPPORTED', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)
FROM moca.benefit_offers offer
INNER JOIN moca.card_benefits benefit ON benefit.benefit_id = offer.benefit_id
INNER JOIN moca.card_content_versions version
    ON version.content_version_id = benefit.content_version_id
INNER JOIN moca.cards card ON card.card_id = version.card_id
WHERE card.gorilla_card_id = '360'
  AND offer.position IN (2, 3)
  AND NOT EXISTS (
      SELECT 1 FROM moca.benefit_rules rule_data
      WHERE rule_data.offer_id = offer.offer_id AND rule_data.position = 1
  );

UPDATE moca.benefit_rules rule_data
INNER JOIN moca.benefit_offers offer ON offer.offer_id = rule_data.offer_id
INNER JOIN moca.card_benefits benefit ON benefit.benefit_id = offer.benefit_id
INNER JOIN moca.card_content_versions version
    ON version.content_version_id = benefit.content_version_id
INNER JOIN moca.cards card ON card.card_id = version.card_id
SET rule_data.previous_spend_min_krw = NULL,
    rule_data.updated_at = UTC_TIMESTAMP(6)
WHERE card.gorilla_card_id = '360'
  AND benefit.title = '모든가맹점'
  AND offer.offer_name = '전 가맹점 기본적립 0.2%'
  AND rule_data.position = 1;

INSERT INTO moca.benefit_rule_targets
    (target_id, rule_id, condition_group, match_mode, target_type,
     merchant_category_id, merchant_id, target_code, target_name,
     target_source, target_authority, minimum_place_confidence, created_at, updated_at)
SELECT UUID(), rule_data.rule_id, 1, 'include', 'all_merchants',
       NULL, NULL, 'ALL', '전 가맹점',
       'ALL_MERCHANTS', 'ALL_MERCHANTS', 0.000,
       CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)
FROM moca.benefit_rules rule_data
INNER JOIN moca.benefit_offers offer ON offer.offer_id = rule_data.offer_id
WHERE offer.offer_name = '전 가맹점 기본적립 0.2%'
  AND NOT EXISTS (
      SELECT 1 FROM moca.benefit_rule_targets target
      WHERE target.rule_id = rule_data.rule_id
        AND target.match_mode = 'include'
        AND target.target_type = 'all_merchants'
  );

