       (5, '올리브영'), (6, 'CGV'), (7, '스타벅스'), (8, '파리바게뜨');

INSERT INTO moca.benefit_rule_targets
    (target_id, rule_id, condition_group, match_mode, target_type,
     merchant_category_id, merchant_id, target_code, target_name,
     target_source, target_authority, minimum_place_confidence, created_at, updated_at)
SELECT UUID(), rule_data.rule_id, seed.condition_group, 'include', 'merchant',
       NULL, merchant.merchant_id, seed.merchant_name, seed.merchant_name,
       'CARD_BENEFIT_EXPLICIT', 'MERCHANT_EXACT', 0.990,
       CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)
FROM moca.benefit_rules rule_data
INNER JOIN moca.benefit_offers offer ON offer.offer_id = rule_data.offer_id
CROSS JOIN seed_nh_point_extra_merchants seed
INNER JOIN moca.merchants merchant ON merchant.normalized_name = seed.merchant_name
WHERE offer.offer_name = '생활 영역 추가적립 0.3%'
  AND NOT EXISTS (
      SELECT 1 FROM moca.benefit_rule_targets target
      WHERE target.rule_id = rule_data.rule_id
        AND target.condition_group = seed.condition_group
        AND target.match_mode = 'include'
        AND target.target_type = 'merchant'
        AND target.merchant_id = merchant.merchant_id
  );

DROP TEMPORARY TABLE seed_nh_point_extra_merchants;

UPDATE moca.card_benefits
SET structuring_status = 'EXCLUDED',
    structuring_note = '혜택 레코드가 아니므로 추천 구조화 대상에서 제외'
WHERE record_type <> 'benefit';

UPDATE moca.card_benefits benefit
INNER JOIN moca.benefit_offers offer ON offer.benefit_id = benefit.benefit_id
SET benefit.structuring_status = 'UNSUPPORTED',
    benefit.structuring_note = CONCAT('현재 지도 추천 미지원 reward_type: ', offer.reward_type)
WHERE benefit.record_type = 'benefit'
  AND offer.reward_type IN ('fee_waiver', 'voucher', 'free_service', 'installment', 'insurance');

UPDATE moca.card_benefits benefit
SET benefit.structuring_status = 'STRUCTURED',
    benefit.structuring_note = NULL
WHERE EXISTS (
    SELECT 1
    FROM moca.benefit_offers offer
    INNER JOIN moca.benefit_rules rule_data ON rule_data.offer_id = offer.offer_id
    INNER JOIN moca.benefit_rule_targets target ON target.rule_id = rule_data.rule_id
    WHERE offer.benefit_id = benefit.benefit_id
      AND target.match_mode = 'include'
      AND offer.reward_type IN ('discount', 'cashback', 'points', 'rebate')
      AND rule_data.rule_effect = 'grant'
      AND rule_data.reward_value IS NOT NULL
      AND rule_data.reward_unit IN ('percent', 'KRW', 'point', 'mile')
      AND target.target_type IN ('all_merchants', 'merchant_category', 'merchant')
);

UPDATE moca.card_benefits benefit
SET benefit.structuring_status = 'PARSE_FAILED',
    benefit.structuring_note = '금전성 문구는 있으나 안전한 offer/rule/target 구조화가 완료되지 않음'
WHERE benefit.record_type = 'benefit'
  AND benefit.structuring_status = 'RAW'
  AND CONCAT_WS(' ', benefit.detail_text, benefit.summary, benefit.title) REGEXP
      '할인|적립|캐시백|포인트|마일리지|청구';

UPDATE moca.card_benefits benefit
SET benefit.structuring_status = 'NON_MONETARY',
    benefit.structuring_note = '금전 가치로 계산할 수 있는 할인·적립 문구가 없는 정보성 혜택'
WHERE benefit.record_type = 'benefit'
  AND benefit.structuring_status = 'RAW'
  AND CONCAT_WS(' ', benefit.detail_text, benefit.summary, benefit.title) NOT REGEXP
      '할인|적립|캐시백|포인트|마일리지|청구';

UPDATE moca.card_benefits benefit
INNER JOIN moca.card_content_versions version
    ON version.content_version_id = benefit.content_version_id
INNER JOIN moca.cards card ON card.card_id = version.card_id
SET benefit.structuring_status = 'PARTIAL',
    benefit.structuring_note = '기본 0.2%와 생활 영역 추가 0.3%만 구조화; 하나로고객·해외 조건은 미지원'
WHERE card.gorilla_card_id = '360'
  AND benefit.title = '모든가맹점';

-- 신한카드 Point Plan 체크 캐릭터형(짱구): 원문으로 확정 가능한 편의점 5% 적립.
INSERT INTO benefit_offers
    (offer_id, benefit_id, reward_program_id, offer_name, position, priority,
     exclusive_group_key, reward_type, value_type, value_unit, calculation_mode,
     calculation_basis, stacking_mode, reward_timing, valuation_scope,
     valuation_method, valid_from, valid_to, created_at, updated_at)
SELECT UUID(), benefit.benefit_id, NULL, '편의점 포인트 적립', 1, 100,
       'SHINHAN_POINT_PLAN_CHECK_CONVENIENCE', 'points', 'percentage', 'percent',
       'flat', 'transaction_amount', 'standalone', 'point_accrual', 'transaction',
       'direct', NULL, NULL, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)
FROM card_benefits benefit
WHERE benefit.benefit_id = '4da2cd93-b8e1-585c-bae4-7118aef652f8'
  AND NOT EXISTS (
      SELECT 1
      FROM benefit_offers existing
      WHERE existing.benefit_id = benefit.benefit_id
        AND existing.position = 1
  );

UPDATE benefit_offers offer
INNER JOIN card_benefits benefit ON benefit.benefit_id = offer.benefit_id
SET offer.offer_name = '편의점 포인트 적립', offer.priority = 100,
    offer.exclusive_group_key = 'SHINHAN_POINT_PLAN_CHECK_CONVENIENCE',
    offer.reward_type = 'points', offer.value_type = 'percentage',
    offer.value_unit = 'percent', offer.calculation_mode = 'flat',
    offer.calculation_basis = 'transaction_amount', offer.stacking_mode = 'standalone',
    offer.reward_timing = 'point_accrual', offer.valuation_scope = 'transaction',
    offer.valuation_method = 'direct', offer.updated_at = UTC_TIMESTAMP(6)
WHERE benefit.benefit_id = '4da2cd93-b8e1-585c-bae4-7118aef652f8'
  AND offer.position = 1;

INSERT INTO benefit_rules
    (rule_id, offer_id, position, priority, rule_name, rule_effect, stacking_mode,
     reward_value, reward_unit, previous_spend_min_krw, rounding_type, rounding_unit,
     rule_schema_version, rule_support_status, rule_definition_json, created_at, updated_at)
SELECT UUID(), offer.offer_id, 1, 100, '편의점',
       'grant', 'standalone', 5, 'percent', 200000, 'floor', 1, 1, 'SUPPORTED',
       JSON_OBJECT(
           'schemaVersion', 1,
           'conditions', JSON_OBJECT(
               'all', JSON_ARRAY(
                   JSON_OBJECT('type', 'PREVIOUS_MONTH_SPEND', 'operator', 'GTE',
                               'value', '200000',
                               'rejectionReason', 'PERFORMANCE_NOT_MET')),
               'any', JSON_ARRAY(), 'none', JSON_ARRAY()),
           'reward', JSON_OBJECT('benefitType', 'POINT', 'rewardUnit', 'POINT',
                                 'calculation', 'RATE', 'rate', '0.05'),
           'limits', JSON_ARRAY(
               JSON_OBJECT('type', 'DAILY_USAGE_COUNT', 'value', '1'))),
       UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)
FROM benefit_offers offer
WHERE offer.benefit_id = '4da2cd93-b8e1-585c-bae4-7118aef652f8'
  AND offer.position = 1
  AND NOT EXISTS (
      SELECT 1
      FROM benefit_rules existing
      WHERE existing.offer_id = offer.offer_id
        AND existing.position = 1
  );

UPDATE benefit_rules rule_data
INNER JOIN benefit_offers offer ON offer.offer_id = rule_data.offer_id
SET rule_data.rule_name = '편의점',
    rule_data.updated_at = UTC_TIMESTAMP(6)
WHERE offer.benefit_id = '4da2cd93-b8e1-585c-bae4-7118aef652f8'
  AND offer.position = 1
  AND rule_data.position = 1;

DELETE target
FROM benefit_rule_targets target
INNER JOIN benefit_rules rule_data ON rule_data.rule_id = target.rule_id
INNER JOIN benefit_offers offer ON offer.offer_id = rule_data.offer_id
WHERE offer.benefit_id = '4da2cd93-b8e1-585c-bae4-7118aef652f8'
  AND offer.position = 1
  AND rule_data.position = 1
  AND target.match_mode = 'include'
  AND target.target_type = 'merchant_category'
  AND target.target_code = 'CONVENIENCE_STORE';

INSERT INTO benefit_rule_targets
    (target_id, rule_id, condition_group, match_mode, target_type,
     merchant_category_id, merchant_id, target_code, target_name,
     target_source, target_authority, minimum_place_confidence, created_at, updated_at)
SELECT UUID(), rule_data.rule_id, merchant_seed.condition_group, 'include', 'merchant',
       NULL, merchant.merchant_id, merchant.normalized_name, merchant.name,
       'CARD_BENEFIT_EXPLICIT', 'MERCHANT_EXACT', 0.990,
       UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)
FROM benefit_rules rule_data
INNER JOIN benefit_offers offer ON offer.offer_id = rule_data.offer_id
INNER JOIN (
    SELECT 1 AS condition_group,
           _utf8mb4'CU' COLLATE utf8mb4_unicode_ci AS merchant_name
    UNION ALL
    SELECT 2, _utf8mb4'GS25' COLLATE utf8mb4_unicode_ci
    UNION ALL
    SELECT 3, _utf8mb4'세븐일레븐' COLLATE utf8mb4_unicode_ci
) merchant_seed ON 1 = 1
INNER JOIN merchants merchant ON merchant.normalized_name = merchant_seed.merchant_name
WHERE offer.benefit_id = '4da2cd93-b8e1-585c-bae4-7118aef652f8'
  AND offer.position = 1
  AND rule_data.position = 1
  AND NOT EXISTS (
      SELECT 1
      FROM benefit_rule_targets existing
      WHERE existing.rule_id = rule_data.rule_id
        AND existing.condition_group = merchant_seed.condition_group
        AND existing.match_mode = 'include'
        AND existing.target_type = 'merchant'
        AND existing.merchant_id = merchant.merchant_id
  );

INSERT INTO benefit_limit_policies
    (limit_policy_id, offer_id, policy_name, limit_period, limit_type, limit_unit,
     shared_group_key, created_at, updated_at)
SELECT UUID(), offer.offer_id, '편의점 포인트 월 통합 적립 한도',
       'monthly', 'reward_amount', 'point', NULL, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)
FROM benefit_offers offer
WHERE offer.benefit_id = '4da2cd93-b8e1-585c-bae4-7118aef652f8'
  AND offer.position = 1
  AND NOT EXISTS (
      SELECT 1
      FROM benefit_limit_policies existing
      WHERE existing.offer_id = offer.offer_id
        AND existing.policy_name = '편의점 포인트 월 통합 적립 한도'
  );

INSERT INTO benefit_limit_tiers
    (limit_tier_id, limit_policy_id, position, limit_value,
     previous_spend_min_krw, current_spend_min_krw, created_at, updated_at)
SELECT UUID(), policy.limit_policy_id, 1, 3000, 200000, NULL,
       UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)
FROM benefit_limit_policies policy
INNER JOIN benefit_offers offer ON offer.offer_id = policy.offer_id
WHERE offer.benefit_id = '4da2cd93-b8e1-585c-bae4-7118aef652f8'
  AND offer.position = 1
  AND policy.policy_name = '편의점 포인트 월 통합 적립 한도'
  AND NOT EXISTS (
      SELECT 1
      FROM benefit_limit_tiers existing
      WHERE existing.limit_policy_id = policy.limit_policy_id
  );

UPDATE card_benefits
SET structuring_status = 'STRUCTURED', structuring_note = NULL,
    updated_at = UTC_TIMESTAMP(6)
WHERE benefit_id = '4da2cd93-b8e1-585c-bae4-7118aef652f8';

-- 신한카드 나라사랑카드 체크: 승인 데이터로 판별 가능한 Life 서비스만 자동 계산한다.
INSERT INTO merchants
    (merchant_id, merchant_category_id, name, normalized_name, status,
     has_physical_location, created_at, updated_at)
SELECT UUID(), category.merchant_category_id, source.name, source.name, 'active',
       source.physical, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)
FROM (
    SELECT 'TAXI' category_code, '카카오T' name, FALSE physical UNION ALL
    SELECT 'CAFE', '컴포즈커피', TRUE UNION ALL
    SELECT 'CAFE', '매머드커피', TRUE UNION ALL
    SELECT 'CAFE', '빽다방', TRUE UNION ALL
    SELECT 'THEME_PARK', '캐리비안베이', TRUE
) source
INNER JOIN merchant_categories category ON category.category_code = source.category_code
WHERE NOT EXISTS (
    SELECT 1 FROM merchants existing WHERE existing.normalized_name = source.name
);

DELETE tier
FROM benefit_limit_tiers tier
INNER JOIN benefit_limit_policies policy ON policy.limit_policy_id = tier.limit_policy_id
INNER JOIN benefit_offers offer ON offer.offer_id = policy.offer_id
WHERE offer.benefit_id IN (
    'd2f751e7-87db-5c87-80da-3566a3f87686',
    'a199918c-17f4-5bd5-a366-2c8c4171f946');

DELETE policy
FROM benefit_limit_policies policy
INNER JOIN benefit_offers offer ON offer.offer_id = policy.offer_id
WHERE offer.benefit_id IN (
    'd2f751e7-87db-5c87-80da-3566a3f87686',
    'a199918c-17f4-5bd5-a366-2c8c4171f946');

DELETE target
FROM benefit_rule_targets target
INNER JOIN benefit_rules rule_data ON rule_data.rule_id = target.rule_id
INNER JOIN benefit_offers offer ON offer.offer_id = rule_data.offer_id
WHERE offer.benefit_id IN (
    'd2f751e7-87db-5c87-80da-3566a3f87686',
    'a199918c-17f4-5bd5-a366-2c8c4171f946');

DELETE rule_data
FROM benefit_rules rule_data
INNER JOIN benefit_offers offer ON offer.offer_id = rule_data.offer_id
WHERE offer.benefit_id IN (
    'd2f751e7-87db-5c87-80da-3566a3f87686',
    'a199918c-17f4-5bd5-a366-2c8c4171f946');

DELETE FROM benefit_offers
WHERE benefit_id IN (
    'd2f751e7-87db-5c87-80da-3566a3f87686',
    'a199918c-17f4-5bd5-a366-2c8c4171f946');

INSERT INTO benefit_offers
    (offer_id, benefit_id, offer_name, position, reward_type, value_type,
     calculation_mode, calculation_basis, stacking_mode, valuation_scope,
     valuation_method, created_at, updated_at)
SELECT source.offer_id, source.benefit_id, source.offer_name, source.position,
       source.reward_type, source.value_type, source.calculation_mode,
       'transaction_amount', 'standalone', 'transaction', source.valuation_method,
       UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)
FROM (
    SELECT '29330000-0000-4000-8000-000000000001' offer_id,
           'd2f751e7-87db-5c87-80da-3566a3f87686' benefit_id,
           '대중교통 20% 캐시백' offer_name, 1 position,
           'cashback' reward_type, 'percentage' value_type,
           'flat' calculation_mode, 'direct' valuation_method UNION ALL
    SELECT '29330000-0000-4000-8000-000000000002',
           'd2f751e7-87db-5c87-80da-3566a3f87686',
           '광역교통 10% 캐시백', 2, 'cashback', 'percentage', 'flat', 'direct' UNION ALL
    SELECT '29330000-0000-4000-8000-000000000003',
           'd2f751e7-87db-5c87-80da-3566a3f87686',
           '카카오T 택시 10% 캐시백', 3, 'cashback', 'percentage', 'flat', 'direct' UNION ALL
    SELECT '29330000-0000-4000-8000-000000000004',
           'd2f751e7-87db-5c87-80da-3566a3f87686',
           '편의점 20% 캐시백', 4, 'cashback', 'percentage', 'flat', 'direct' UNION ALL
    SELECT '29330000-0000-4000-8000-000000000005',
           'd2f751e7-87db-5c87-80da-3566a3f87686',
           '주요 커피 브랜드 5% 캐시백', 5, 'cashback', 'percentage', 'flat', 'direct' UNION ALL
    SELECT '29330000-0000-4000-8000-000000000006',
           'a199918c-17f4-5bd5-a366-2c8c4171f946',
           'CGV 관람권 6천원 정액 제공', 1, 'other', 'other', 'other', 'not_valued' UNION ALL
    SELECT '29330000-0000-4000-8000-000000000007',
           'a199918c-17f4-5bd5-a366-2c8c4171f946',
           '테마파크 최대 50% 할인', 2, 'discount', 'percentage', 'flat', 'not_valued' UNION ALL
    SELECT '29330000-0000-4000-8000-000000000008',
           'a199918c-17f4-5bd5-a366-2c8c4171f946',
           'CU 행사상품 10% 즉시할인', 3, 'discount', 'percentage', 'flat', 'not_valued'
) source
WHERE EXISTS (SELECT 1 FROM card_benefits benefit WHERE benefit.benefit_id = source.benefit_id)
  AND NOT EXISTS (SELECT 1 FROM benefit_offers existing WHERE existing.offer_id = source.offer_id);

INSERT INTO benefit_rules
    (rule_id, offer_id, position, rule_name, rule_effect, stacking_mode,
     reward_value, reward_unit, previous_spend_min_krw,
     rule_schema_version, rule_support_status, rule_definition_json,
     created_at, updated_at)
SELECT source.rule_id, source.offer_id, 1, source.offer_name, 'grant', 'standalone',
       source.rate * 100, 'percent', 100000, 1, 'SUPPORTED',
       JSON_OBJECT(
           'schemaVersion', 1,
           'conditions', JSON_OBJECT(
               'all', JSON_ARRAY(JSON_OBJECT(
                   'type', 'PREVIOUS_MONTH_SPEND', 'operator', 'GTE',
                   'value', '100000', 'rejectionReason', 'PERFORMANCE_NOT_MET')),
               'any', JSON_ARRAY(), 'none', JSON_ARRAY()),
           'reward', JSON_OBJECT(
               'benefitType', 'CASHBACK', 'rewardUnit', 'KRW',
               'calculation', 'RATE', 'rate', CAST(source.rate AS CHAR)),
           'limits', CASE source.offer_id
               WHEN '29330000-0000-4000-8000-000000000004' THEN JSON_ARRAY(
                   JSON_OBJECT('type', 'TRANSACTION_BENEFIT_BASE', 'value', '5000'),
                   JSON_OBJECT('type', 'DAILY_USAGE_COUNT', 'value', '1'),
                   JSON_OBJECT('type', 'MONTHLY_USAGE_COUNT', 'value', '5'))
               WHEN '29330000-0000-4000-8000-000000000005' THEN JSON_ARRAY(
                   JSON_OBJECT('type', 'TRANSACTION_BENEFIT_BASE', 'value', '40000'),
                   JSON_OBJECT('type', 'DAILY_USAGE_COUNT', 'value', '1'),
                   JSON_OBJECT('type', 'MONTHLY_USAGE_COUNT', 'value', '3'))
               ELSE JSON_ARRAY()
           END),
       UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)
FROM (
    SELECT '29330000-0000-4000-8000-000000000101' rule_id,
           '29330000-0000-4000-8000-000000000001' offer_id,
           '대중교통 20% 캐시백' offer_name, 0.20 rate UNION ALL
    SELECT '29330000-0000-4000-8000-000000000102',
           '29330000-0000-4000-8000-000000000002', '광역교통 10% 캐시백', 0.10 UNION ALL
    SELECT '29330000-0000-4000-8000-000000000104',
           '29330000-0000-4000-8000-000000000004', '편의점 20% 캐시백', 0.20 UNION ALL
    SELECT '29330000-0000-4000-8000-000000000105',
           '29330000-0000-4000-8000-000000000005', '주요 커피 브랜드 5% 캐시백', 0.05
) source
WHERE EXISTS (SELECT 1 FROM benefit_offers offer WHERE offer.offer_id = source.offer_id)
  AND NOT EXISTS (SELECT 1 FROM benefit_rules existing WHERE existing.rule_id = source.rule_id);

INSERT INTO benefit_rules
    (rule_id, offer_id, position, rule_name, rule_effect, stacking_mode,
     reward_value, reward_unit, rule_schema_version, rule_support_status,
     rule_definition_json, created_at, updated_at)
SELECT source.rule_id, source.offer_id, 1, source.offer_name, 'grant', 'standalone',
       source.reward_value, source.reward_unit, 1, 'INFORMATION_ONLY',
       JSON_OBJECT('schemaVersion', 1, 'mode', 'INFORMATION_ONLY',
                   'reason', source.reason), UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)
FROM (
    SELECT '29330000-0000-4000-8000-000000000103' rule_id,
           '29330000-0000-4000-8000-000000000003' offer_id,
           '카카오T 택시 10% 캐시백' offer_name, 10 reward_value,
           'percent' reward_unit,
           'PAYMENT_CHANNEL_AND_TAXI_SERVICE_NOT_VERIFIABLE' reason UNION ALL
    SELECT '29330000-0000-4000-8000-000000000106' rule_id,
           '29330000-0000-4000-8000-000000000006' offer_id,
           'CGV 관람권 6천원 정액 제공' offer_name, NULL reward_value,
           NULL reward_unit, 'TICKET_PRICE_AND_QUANTITY_NOT_VERIFIABLE' reason UNION ALL
    SELECT '29330000-0000-4000-8000-000000000107',
           '29330000-0000-4000-8000-000000000007',
           '테마파크 최대 50% 할인', 50, 'percent',
           'ANNUAL_COUNT_AND_TICKET_HOLDER_NOT_VERIFIABLE' UNION ALL
    SELECT '29330000-0000-4000-8000-000000000108',
           '29330000-0000-4000-8000-000000000008',
           'CU 행사상품 10% 즉시할인', 10, 'percent',
           'EVENT_PRODUCT_NOT_VERIFIABLE'
) source
WHERE EXISTS (SELECT 1 FROM benefit_offers offer WHERE offer.offer_id = source.offer_id)
  AND NOT EXISTS (SELECT 1 FROM benefit_rules existing WHERE existing.rule_id = source.rule_id);

INSERT INTO benefit_rule_targets
    (target_id, rule_id, condition_group, match_mode, target_type,
     merchant_category_id, merchant_id, target_code, target_name,
     target_source, target_authority, minimum_place_confidence, created_at, updated_at)
SELECT UUID(), source.rule_id, source.condition_group, 'include', source.target_type,
       category.merchant_category_id, merchant.merchant_id, source.target_code, source.target_code,
       'CARD_BENEFIT_EXPLICIT',
       CASE source.target_type WHEN 'merchant' THEN 'MERCHANT_EXACT' ELSE 'ISSUER_CATEGORY' END,
       0.990, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)
FROM (
    SELECT '29330000-0000-4000-8000-000000000101' rule_id, 1 condition_group,
           'merchant_category' target_type, 'BUS' target_code UNION ALL
    SELECT '29330000-0000-4000-8000-000000000101', 2, 'merchant_category', 'SUBWAY' UNION ALL
    SELECT '29330000-0000-4000-8000-000000000102', 1, 'merchant_category', 'EXPRESS_BUS' UNION ALL
    SELECT '29330000-0000-4000-8000-000000000102', 2, 'merchant_category', 'TRAIN' UNION ALL
    SELECT '29330000-0000-4000-8000-000000000103', 1, 'merchant', '카카오T' UNION ALL
    SELECT '29330000-0000-4000-8000-000000000104', 1, 'merchant', 'GS25' UNION ALL
    SELECT '29330000-0000-4000-8000-000000000104', 2, 'merchant', 'CU' UNION ALL
    SELECT '29330000-0000-4000-8000-000000000105', 1, 'merchant', '스타벅스' UNION ALL
    SELECT '29330000-0000-4000-8000-000000000105', 2, 'merchant', '이디야' UNION ALL
    SELECT '29330000-0000-4000-8000-000000000105', 3, 'merchant', '메가MGC커피' UNION ALL
    SELECT '29330000-0000-4000-8000-000000000105', 4, 'merchant', '폴바셋' UNION ALL
    SELECT '29330000-0000-4000-8000-000000000105', 5, 'merchant', '컴포즈커피' UNION ALL
    SELECT '29330000-0000-4000-8000-000000000105', 6, 'merchant', '매머드커피' UNION ALL
    SELECT '29330000-0000-4000-8000-000000000105', 7, 'merchant', '빽다방'
    UNION ALL SELECT '29330000-0000-4000-8000-000000000106', 1, 'merchant', 'CGV'
    UNION ALL SELECT '29330000-0000-4000-8000-000000000107', 1, 'merchant', '에버랜드'
    UNION ALL SELECT '29330000-0000-4000-8000-000000000107', 2, 'merchant', '롯데월드'
    UNION ALL SELECT '29330000-0000-4000-8000-000000000107', 3, 'merchant', '서울랜드'
    UNION ALL SELECT '29330000-0000-4000-8000-000000000107', 4, 'merchant', '캐리비안베이'
    UNION ALL SELECT '29330000-0000-4000-8000-000000000108', 1, 'merchant', 'CU'
) source
LEFT JOIN merchant_categories category
    ON source.target_type = 'merchant_category' AND category.category_code = source.target_code
LEFT JOIN merchants merchant
    ON source.target_type = 'merchant' AND merchant.normalized_name = source.target_code
WHERE NOT EXISTS (
    SELECT 1 FROM benefit_rule_targets existing
    WHERE existing.rule_id = source.rule_id
      AND existing.condition_group = source.condition_group
      AND existing.match_mode = 'include'
      AND existing.target_type = source.target_type
      AND existing.target_code = source.target_code
)
  AND EXISTS (SELECT 1 FROM benefit_rules rule_data WHERE rule_data.rule_id = source.rule_id)
  AND (category.merchant_category_id IS NOT NULL OR merchant.merchant_id IS NOT NULL);

INSERT INTO benefit_limit_policies
    (limit_policy_id, offer_id, policy_name, limit_period, limit_type, limit_unit,
     shared_group_key, created_at, updated_at)
SELECT CONCAT('29330000-0000-4000-8000-0000000002', LPAD(source.position, 2, '0')),
       source.offer_id, 'Life 서비스 통합 캐시백 한도',
       'monthly', 'reward_amount', 'KRW', 'SHINHAN_NARASARANG_LIFE',
       UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)
FROM (
    SELECT 1 position, '29330000-0000-4000-8000-000000000001' offer_id UNION ALL
    SELECT 2, '29330000-0000-4000-8000-000000000002' UNION ALL
    SELECT 3, '29330000-0000-4000-8000-000000000003' UNION ALL
    SELECT 4, '29330000-0000-4000-8000-000000000004' UNION ALL
    SELECT 5, '29330000-0000-4000-8000-000000000005'
) source
WHERE EXISTS (SELECT 1 FROM benefit_offers offer WHERE offer.offer_id = source.offer_id)
  AND NOT EXISTS (SELECT 1 FROM benefit_limit_policies existing
                  WHERE existing.offer_id = source.offer_id
                    AND existing.shared_group_key = 'SHINHAN_NARASARANG_LIFE');

INSERT INTO benefit_limit_tiers
    (limit_tier_id, limit_policy_id, position, limit_value,
     previous_spend_min_krw, created_at, updated_at)
SELECT UUID(), policy.limit_policy_id, tier_data.position, tier_data.limit_value,
       tier_data.minimum_spend, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)
FROM benefit_limit_policies policy
INNER JOIN benefit_offers offer ON offer.offer_id = policy.offer_id
INNER JOIN (
    SELECT 1 position, 5000 limit_value, 100000 minimum_spend UNION ALL
    SELECT 2, 20000, 200000 UNION ALL
    SELECT 3, 30000, 500000 UNION ALL
    SELECT 4, 40000, 700000 UNION ALL
    SELECT 5, 50000, 1000000
) tier_data
WHERE offer.offer_id IN (
    '29330000-0000-4000-8000-000000000001',
    '29330000-0000-4000-8000-000000000002',
    '29330000-0000-4000-8000-000000000003',
    '29330000-0000-4000-8000-000000000004',
    '29330000-0000-4000-8000-000000000005')
  AND policy.shared_group_key = 'SHINHAN_NARASARANG_LIFE'
  AND NOT EXISTS (SELECT 1 FROM benefit_limit_tiers existing
                  WHERE existing.limit_policy_id = policy.limit_policy_id
                    AND existing.position = tier_data.position);

-- Life 통합 한도와 별도로 각 서비스의 월간 캐시백 상한을 보존한다.
-- OFFER 그룹 키는 통합 한도 후보와 분리해 서비스에서 두 한도를 모두 적용한다.
INSERT INTO benefit_limit_policies
    (limit_policy_id, offer_id, policy_name, limit_period, limit_type, limit_unit,
     shared_group_key, created_at, updated_at)
SELECT source.limit_policy_id, source.offer_id, source.policy_name,
       'monthly', 'reward_amount', 'KRW', CONCAT('OFFER:', source.offer_id),
       UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)
FROM (
    SELECT '29330000-0000-4000-8000-000000000301' limit_policy_id,
           '29330000-0000-4000-8000-000000000001' offer_id,
           '대중교통 월 캐시백 한도' policy_name UNION ALL
    SELECT '29330000-0000-4000-8000-000000000302',
           '29330000-0000-4000-8000-000000000002', '광역교통 월 캐시백 한도' UNION ALL
    SELECT '29330000-0000-4000-8000-000000000303',
           '29330000-0000-4000-8000-000000000003', '카카오T 택시 월 캐시백 한도' UNION ALL
    SELECT '29330000-0000-4000-8000-000000000304',
           '29330000-0000-4000-8000-000000000004', '편의점 월 캐시백 한도' UNION ALL
    SELECT '29330000-0000-4000-8000-000000000305',
           '29330000-0000-4000-8000-000000000005', '주요 커피 브랜드 월 캐시백 한도'
) source
WHERE EXISTS (SELECT 1 FROM benefit_offers offer WHERE offer.offer_id = source.offer_id)
  AND NOT EXISTS (SELECT 1 FROM benefit_limit_policies existing
                  WHERE existing.limit_policy_id = source.limit_policy_id);

INSERT INTO benefit_limit_tiers
    (limit_tier_id, limit_policy_id, position, limit_value,
     previous_spend_min_krw, created_at, updated_at)
SELECT UUID(), source.limit_policy_id, 1, source.limit_value,
       100000, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)
FROM (
    SELECT '29330000-0000-4000-8000-000000000301' limit_policy_id,
           5000 limit_value UNION ALL
    SELECT '29330000-0000-4000-8000-000000000302', 3000 UNION ALL
    SELECT '29330000-0000-4000-8000-000000000303', 2000 UNION ALL
    SELECT '29330000-0000-4000-8000-000000000304', 5000 UNION ALL
    SELECT '29330000-0000-4000-8000-000000000305', 6000
) source
WHERE EXISTS (SELECT 1 FROM benefit_limit_policies policy
              WHERE policy.limit_policy_id = source.limit_policy_id)
  AND NOT EXISTS (SELECT 1 FROM benefit_limit_tiers existing
                  WHERE existing.limit_policy_id = source.limit_policy_id
                    AND existing.position = 1);

-- Point Plan 체크 캐릭터형: 일상 생활비 적립과 일반월·가족행사월 한도.
INSERT INTO benefit_offers
    (offer_id, benefit_id, offer_name, position, priority, exclusive_group_key,
     reward_type, value_type, value_unit, calculation_mode, calculation_basis,
     stacking_mode, reward_timing, valuation_scope, valuation_method,
     created_at, updated_at)
SELECT UUID(), benefit.benefit_id,
       '일상 생활비 포인트 적립', 1, 90,
       'SHINHAN_POINT_PLAN_CHECK_DAILY_LIVING', 'points', 'percentage', 'percent',
       'flat', 'transaction_amount', 'standalone', 'point_accrual', 'transaction',
       'direct', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)
FROM card_benefits benefit
WHERE benefit.benefit_id = '44b5ee1e-3227-552b-846e-ff21dda17402'
  AND NOT EXISTS (
      SELECT 1 FROM benefit_offers existing
      WHERE existing.benefit_id = benefit.benefit_id
        AND existing.position = 1);

UPDATE benefit_offers offer
SET offer.offer_name = '일상 생활비 포인트 적립', offer.priority = 90,
    offer.exclusive_group_key = 'SHINHAN_POINT_PLAN_CHECK_DAILY_LIVING',
    offer.reward_type = 'points', offer.value_type = 'percentage',
    offer.value_unit = 'percent', offer.calculation_mode = 'flat',
    offer.calculation_basis = 'transaction_amount', offer.stacking_mode = 'standalone',
    offer.reward_timing = 'point_accrual', offer.valuation_scope = 'transaction',
    offer.valuation_method = 'direct', offer.updated_at = UTC_TIMESTAMP(6)
WHERE offer.benefit_id = '44b5ee1e-3227-552b-846e-ff21dda17402'
  AND offer.position = 1;

INSERT INTO benefit_rules
    (rule_id, offer_id, position, priority, rule_name, rule_effect, stacking_mode,
     reward_value, reward_unit, previous_spend_min_krw, rounding_type, rounding_unit,
     rule_schema_version, rule_support_status, rule_definition_json,
     created_at, updated_at)
SELECT CONCAT('28900000-0000-4000-8000-0000000001', LPAD(source.position, 2, '0')),
       offer.offer_id, source.position, source.position,
       source.rule_name, 'grant', 'standalone', source.rate * 100, 'percent',
       200000, 'floor', 1, 1, 'SUPPORTED',
       JSON_OBJECT(
           'schemaVersion', 1,
           'conditions', JSON_OBJECT(
               'all', JSON_ARRAY(
                   JSON_OBJECT('type', 'PAYMENT_AMOUNT', 'operator', 'GTE',
                               'value', CAST(source.minimum_amount AS CHAR),
                               'rejectionReason', 'MIN_PAYMENT_NOT_MET'),
                   JSON_OBJECT('type', 'PAYMENT_AMOUNT', 'operator', 'LT',
                               'value', CAST(source.maximum_amount AS CHAR),
                               'rejectionReason', 'CATEGORY_NOT_MATCHED'),
                   JSON_OBJECT('type', 'PREVIOUS_MONTH_SPEND', 'operator', 'GTE',
                               'value', '200000',
                               'rejectionReason', 'PERFORMANCE_NOT_MET')),
               'any', JSON_ARRAY(),
               'none', JSON_ARRAY(JSON_OBJECT(
                   'type', 'MERCHANT_CATEGORY', 'operator', 'IN',
                   'values', JSON_ARRAY('CONVENIENCE_STORE'),
                   'rejectionReason', 'TARGET_NOT_MATCHED'))),
           'reward', JSON_OBJECT('benefitType', 'POINT', 'rewardUnit', 'POINT',
                                 'calculation', 'RATE',
                                 'rate', CAST(source.rate AS CHAR)),
           'limits', JSON_ARRAY()),
       UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)
FROM (
    SELECT 1 position, '일상 생활비' rule_name,
           0 minimum_amount, 20000 maximum_amount, 0.002 rate UNION ALL
    SELECT 2, '일상 생활비', 20000, 100000, 0.004 UNION ALL
    SELECT 3, '일상 생활비', 100000, 500000, 0.008 UNION ALL
    SELECT 4, '일상 생활비', 500000, 999999999999, 0.01
) source
INNER JOIN benefit_offers offer
    ON offer.benefit_id = '44b5ee1e-3227-552b-846e-ff21dda17402'
   AND offer.position = 1
WHERE 1 = 1
  AND NOT EXISTS (
      SELECT 1 FROM benefit_rules existing
      WHERE existing.offer_id = offer.offer_id
        AND existing.position = source.position);

UPDATE benefit_rules rule_data
INNER JOIN benefit_offers offer ON offer.offer_id = rule_data.offer_id
INNER JOIN (
    SELECT 1 position, '일상 생활비' rule_name,
           0 minimum_amount, 20000 maximum_amount, 0.002 rate UNION ALL
    SELECT 2, '일상 생활비', 20000, 100000, 0.004 UNION ALL
    SELECT 3, '일상 생활비', 100000, 500000, 0.008 UNION ALL
    SELECT 4, '일상 생활비', 500000, 999999999999, 0.01
) source ON source.position = rule_data.position
SET rule_data.priority = source.position,
    rule_data.rule_name = source.rule_name,
    rule_data.rule_effect = 'grant',
    rule_data.stacking_mode = 'standalone',
    rule_data.reward_value = source.rate * 100,
    rule_data.reward_unit = 'percent',
    rule_data.previous_spend_min_krw = 200000,
    rule_data.rounding_type = 'floor',
    rule_data.rounding_unit = 1,
    rule_data.rule_schema_version = 1,
    rule_data.rule_support_status = 'SUPPORTED',
    rule_data.rule_definition_json = JSON_OBJECT(
        'schemaVersion', 1,
        'conditions', JSON_OBJECT(
            'all', JSON_ARRAY(
                JSON_OBJECT('type', 'PAYMENT_AMOUNT', 'operator', 'GTE',
                            'value', CAST(source.minimum_amount AS CHAR),
                            'rejectionReason', 'MIN_PAYMENT_NOT_MET'),
                JSON_OBJECT('type', 'PAYMENT_AMOUNT', 'operator', 'LT',
                            'value', CAST(source.maximum_amount AS CHAR),
                            'rejectionReason', 'CATEGORY_NOT_MATCHED'),
                JSON_OBJECT('type', 'PREVIOUS_MONTH_SPEND', 'operator', 'GTE',
                            'value', '200000',
                            'rejectionReason', 'PERFORMANCE_NOT_MET')),
            'any', JSON_ARRAY(),
            'none', JSON_ARRAY(JSON_OBJECT(
                'type', 'MERCHANT_CATEGORY', 'operator', 'IN',
                'values', JSON_ARRAY('CONVENIENCE_STORE'),
                'rejectionReason', 'TARGET_NOT_MATCHED'))),
        'reward', JSON_OBJECT('benefitType', 'POINT', 'rewardUnit', 'POINT',
                              'calculation', 'RATE',
                              'rate', CAST(source.rate AS CHAR)),
        'limits', JSON_ARRAY()),
    rule_data.updated_at = UTC_TIMESTAMP(6)
WHERE offer.benefit_id = '44b5ee1e-3227-552b-846e-ff21dda17402'
  AND offer.position = 1;

INSERT INTO benefit_rule_targets
    (target_id, rule_id, condition_group, match_mode, target_type,
     target_code, target_name, target_source, target_authority,
     minimum_place_confidence, created_at, updated_at)
SELECT UUID(), rule_data.rule_id, 1, 'include', 'all_merchants',
       'ALL', '국내 오프라인 전체 가맹점', 'ALL_MERCHANTS', 'ALL_MERCHANTS',
       0.000, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)
FROM benefit_rules rule_data
INNER JOIN benefit_offers offer ON offer.offer_id = rule_data.offer_id
WHERE offer.benefit_id = '44b5ee1e-3227-552b-846e-ff21dda17402'
  AND offer.position = 1
  AND NOT EXISTS (
      SELECT 1 FROM benefit_rule_targets existing
      WHERE existing.rule_id = rule_data.rule_id
        AND existing.match_mode = 'include'
        AND existing.target_type = 'all_merchants');

DELETE target
FROM benefit_rule_targets target
INNER JOIN benefit_rules rule_data ON rule_data.rule_id = target.rule_id
INNER JOIN benefit_offers offer ON offer.offer_id = rule_data.offer_id
WHERE offer.benefit_id = '44b5ee1e-3227-552b-846e-ff21dda17402'
  AND offer.position = 1
  AND NOT (target.match_mode = 'include' AND target.target_type = 'all_merchants');

UPDATE benefit_rule_targets target
INNER JOIN benefit_rules rule_data ON rule_data.rule_id = target.rule_id
INNER JOIN benefit_offers offer ON offer.offer_id = rule_data.offer_id
SET target.condition_group = 1,
    target.match_mode = 'include',
    target.target_type = 'all_merchants',
    target.merchant_category_id = NULL,
    target.merchant_id = NULL,
    target.target_code = 'ALL',
    target.target_name = '국내 오프라인 전체 가맹점',
    target.target_source = 'ALL_MERCHANTS',
    target.target_authority = 'ALL_MERCHANTS',
    target.minimum_place_confidence = 0.000,
    target.updated_at = UTC_TIMESTAMP(6)
WHERE offer.benefit_id = '44b5ee1e-3227-552b-846e-ff21dda17402'
  AND offer.position = 1;

INSERT INTO benefit_limit_policies
    (limit_policy_id, offer_id, policy_name, limit_period, limit_type, limit_unit,
     shared_group_key, created_at, updated_at)
SELECT source.limit_policy_id, offer.offer_id,
       source.policy_name, 'monthly', 'reward_amount', 'point', NULL,
       UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)
FROM (
    SELECT '28900000-0000-4000-8000-000000000201' limit_policy_id,
           '일상 생활비 일반월 한도' policy_name UNION ALL
    SELECT '28900000-0000-4000-8000-000000000202',
           '일상 생활비 가족행사월 한도'
) source
INNER JOIN benefit_offers offer
    ON offer.benefit_id = '44b5ee1e-3227-552b-846e-ff21dda17402'
   AND offer.position = 1
WHERE 1 = 1
  AND NOT EXISTS (
      SELECT 1 FROM benefit_limit_policies existing
      WHERE existing.limit_policy_id = source.limit_policy_id);

UPDATE benefit_limit_policies
SET offer_id = (
        SELECT offer_id FROM benefit_offers
        WHERE benefit_id = '44b5ee1e-3227-552b-846e-ff21dda17402'
          AND position = 1),
    policy_name = CASE limit_policy_id
        WHEN '28900000-0000-4000-8000-000000000201' THEN '일상 생활비 일반월 한도'
        ELSE '일상 생활비 가족행사월 한도' END,
    limit_period = 'monthly',
    limit_type = 'reward_amount',
    limit_unit = 'point',
    shared_group_key = NULL,
    updated_at = UTC_TIMESTAMP(6)
WHERE limit_policy_id IN (
    '28900000-0000-4000-8000-000000000201',
    '28900000-0000-4000-8000-000000000202');

-- V23 스키마에서도 seed를 먼저 적재할 수 있도록 월 컬럼 갱신은 동적 SQL로 수행한다.
SET @point_plan_month_column_exists := (
    SELECT COUNT(*)
    FROM information_schema.columns
    WHERE table_schema = DATABASE()
      AND table_name = 'benefit_limit_policies'
      AND column_name = 'applicable_months_json'
);
SET @point_plan_month_sql := IF(
    @point_plan_month_column_exists > 0,
    'UPDATE benefit_limit_policies SET applicable_months_json = CASE policy_name WHEN ''일상 생활비 일반월 한도'' THEN JSON_ARRAY(1,2,3,4,6,7,8,9,10,11) WHEN ''일상 생활비 가족행사월 한도'' THEN JSON_ARRAY(5,12) ELSE applicable_months_json END WHERE limit_policy_id IN (''28900000-0000-4000-8000-000000000201'',''28900000-0000-4000-8000-000000000202'')',
    'SELECT 1'
);
PREPARE point_plan_month_statement FROM @point_plan_month_sql;
EXECUTE point_plan_month_statement;
DEALLOCATE PREPARE point_plan_month_statement;

INSERT INTO benefit_limit_tiers
    (limit_tier_id, limit_policy_id, position, limit_value,
     previous_spend_min_krw, created_at, updated_at)
SELECT UUID(), source.limit_policy_id, source.position, source.limit_value,
       source.minimum_spend, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)
FROM (
    SELECT '28900000-0000-4000-8000-000000000201' limit_policy_id,
           1 position, 5000 limit_value, 200000 minimum_spend UNION ALL
    SELECT '28900000-0000-4000-8000-000000000201', 2, 10000, 500000 UNION ALL
    SELECT '28900000-0000-4000-8000-000000000201', 3, 15000, 800000 UNION ALL
    SELECT '28900000-0000-4000-8000-000000000202', 1, 10000, 200000 UNION ALL
    SELECT '28900000-0000-4000-8000-000000000202', 2, 15000, 500000 UNION ALL
    SELECT '28900000-0000-4000-8000-000000000202', 3, 20000, 800000
) source
WHERE EXISTS (
    SELECT 1 FROM benefit_limit_policies policy
    WHERE policy.limit_policy_id = source.limit_policy_id)
  AND NOT EXISTS (
      SELECT 1 FROM benefit_limit_tiers existing
      WHERE existing.limit_policy_id = source.limit_policy_id
        AND existing.position = source.position);

UPDATE benefit_limit_tiers tier
INNER JOIN (
    SELECT '28900000-0000-4000-8000-000000000201' limit_policy_id,
           1 position, 5000 limit_value, 200000 minimum_spend UNION ALL
    SELECT '28900000-0000-4000-8000-000000000201', 2, 10000, 500000 UNION ALL
    SELECT '28900000-0000-4000-8000-000000000201', 3, 15000, 800000 UNION ALL
    SELECT '28900000-0000-4000-8000-000000000202', 1, 10000, 200000 UNION ALL
    SELECT '28900000-0000-4000-8000-000000000202', 2, 15000, 500000 UNION ALL
    SELECT '28900000-0000-4000-8000-000000000202', 3, 20000, 800000
) source ON source.limit_policy_id = tier.limit_policy_id
        AND source.position = tier.position
SET tier.limit_value = source.limit_value,
    tier.previous_spend_min_krw = source.minimum_spend,
    tier.current_spend_min_krw = NULL,
    tier.updated_at = UTC_TIMESTAMP(6);

UPDATE card_benefits
SET structuring_status = 'STRUCTURED', structuring_note = NULL,
    updated_at = UTC_TIMESTAMP(6)
WHERE benefit_id = '44b5ee1e-3227-552b-846e-ff21dda17402';
